INSERT INTO "mytable" ("conversation","result","id_conversation")
VALUES
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm mua một chiếc điện thoại mới. Bạn có thể tư vấn giúp tôi không?"},{"speaker":"salebot","text":"Chào bạn! Tôi rất vui được giúp đỡ. Bạn đang quan tâm đến dòng điện thoại nào? Ví dụ như iPhone, Samsung hay thương hiệu khác?"},{"speaker":"client","text":"Tôi đang phân vân giữa iPhone 15 Pro và Samsung Galaxy S24. Bạn có thể so sánh giúp tôi không?"},{"speaker":"salebot","text":"Tất nhiên! iPhone 15 Pro có chip A17 Pro mạnh mẽ, camera 48MP tuyệt vời và hệ điều hành iOS ổn định. Còn Galaxy S24 có màn hình Dynamic AMOLED 2X, chip Snapdragon 8 Gen 3 và hệ điều hành Android mượt mà."},{"speaker":"client","text":"Cảm ơn bạn! Tôi thấy iPhone 15 Pro hợp với sở thích của mình hơn. Bạn có thể báo giá và giao hàng nhanh không?"},{"speaker":"salebot","text":"Chắc chắn rồi! iPhone 15 Pro hiện có giá 28 triệu đồng, giao hàng miễn phí trong 24 giờ tại Hà Nội. Bạn có muốn đặt hàng ngay không?"},{"speaker":"client","text":"Được rồi, tôi đặt mua chiếc iPhone 15 Pro màu xanh dương nhé! Cảm ơn bạn rất nhiều."},{"speaker":"salebot","text":"Cảm ơn bạn đã mua hàng! Chúng tôi sẽ gửi xác nhận đơn hàng qua email và số điện thoại của bạn trong giây lát. Chúc bạn một ngày tốt lành!"}]','successs',0),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm mua một đôi giày chạy bộ cho chị gái tôi. Cô ấy thích màu xanh lam."},{"speaker":"salebot","text":"Chào chị! Rất vui được hỗ trợ chị. Đôi giày chạy bộ màu xanh lam hiện có 2 mẫu: 1 là giày thể thao thông thường, 2 là giày chạy chuyên nghiệp. Chị muốn loại nào?"},{"speaker":"client","text":"Cô ấy thường chạy 5km mỗi ngày, nên cần loại chuyên nghiệp. Giá bao nhiêu?"},{"speaker":"salebot","text":"Dạ, loại chuyên nghiệp giá 2.500.000đ. Nhưng hiện tại hết size 38 rồi chị ạ."},{"speaker":"client","text":"Thế à? Size 37 thì sao? Cô ấy đi vừa size 37."},{"speaker":"salebot","text":"Size 37 cũng hết hàng chị ơi. Chị thông cảm, sản phẩm chạy bộ hot quá. Có màu xanh dương khác không?"},{"speaker":"client","text":"Không, cô ấy thích màu xanh lam. Thế thôi, tôi đi tìm chỗ khác vậy."}]','fail',1),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc điện thoại mới. Bạn có thể tư vấn giúp mình không?"},{"speaker":"salebot","text":"Chào bạn! Mình rất vui được hỗ trợ. Bạn đang quan tâm đến dòng sản phẩm nào? Chẳng hạn như iPhone, Samsung hay các thương hiệu khác?"},{"speaker":"client","text":"Mình thích Samsung, nhưng không biết nên chọn dòng nào. Có phải Galaxy S23 Ultra là tốt nhất không?"},{"speaker":"salebot","text":"Đúng vậy, Galaxy S23 Ultra là dòng cao cấp nhất với camera 200MP, màn hình Dynamic AMOLED 2X 120Hz. Giá hiện tại là 23 triệu, bạn có nhu cầu mua ngay không?"},{"speaker":"client","text":"Ừ, mình thích rồi. Nhưng có giảm giá gì không? Mình thấy trên mạng thấy khuyến mại 5 triệu."},{"speaker":"salebot","text":"Dạ, hiện tại shop đang có chương trình giảm giá 3 triệu cho đơn hàng trong hôm nay. Nếu bạn đặt ngay, mình sẽ gửi kèm 1 tai nghe không dây tặng kèm!"},{"speaker":"client","text":"Tuyệt quá! Vậy mình chọn màu đen nhé. Bao lâu giao được?"},{"speaker":"salebot","text":"Cảm ơn bạn! Đơn hàng sẽ giao trong 2-3 ngày. Bạn vui lòng cung cấp địa chỉ và số điện thoại để mình xử lý nhé."}]','successs',2),
('[{"speaker":"client","text":"Chào bạn! Tôi đang tìm mua một chiếc bàn học gỗ cho con gái tôi. Nó mới vào lớp 1, nên cần bàn vừa kích thước, chắc chắn thôi."},{"speaker":"salebot","text":"Chào chị! Cảm ơn chị đã quan tâm sản phẩm của chúng tôi. Bàn học gỗ cho bé lớp 1 của chị là lựa chọn hoàn hảo đấy ạ. Chúng tôi có loại bàn gỗ thông dụng, kích thước 100x50x75cm, trọng lượng chịu được 50kg, an toàn cho trẻ em."},{"speaker":"client","text":"Ừm, nghe cũng ổn. Nhưng giá bao nhiêu vậy? Tôi thấy nhiều chỗ bán rẻ hơn."},{"speaker":"salebot","text":"Dạ thưa chị, sản phẩm của chúng tôi có giá 1.290.000đ, nhưng chị yên tâm vì chất lượng gỗ thông 100% nhập khẩu, bề mặt phủ sơn chống trầy xước an toàn cho bé. Đi kèm còn có bảo hành 2 năm nữa chị nhé."},{"speaker":"client","text":"Thế bảo hành thế nào? Có dễ sửa chữa không? Tôi nghe nói chỗ khác bảo hành lâu lắm."},{"speaker":"salebot","text":"Dạ thưa chị, chúng tôi cam kết bảo hành tại nhà trong vòng 48 giờ nếu lỗi thuộc về sản phẩm. Ngoài ra, chị có thể đổi trả trong 30 ngày nếu không vừa ý ạ."},{"speaker":"client","text":"Vậy thôi, tôi cân nhắc đã. Cảm ơn bạn nhé!"}]','fail',3),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm mua một chiếc áo khoác gió nhẹ cho mùa đông này. Bạn có thể giới thiệu sản phẩm không?"},{"speaker":"salebot","text":"Chào chị ạ! Chúng tôi có dòng áo khoác gió siêu nhẹ, chống gió tốt, giá 599.000đ thôi chị nhé. Chị thích màu gì?"},{"speaker":"client","text":"Màu xanh navy nhé. Có size S không?"},{"speaker":"salebot","text":"Dạ có ạ! Size S vẫn còn hàng. Chị muốn giao trong ngày hôm nay không?"},{"speaker":"client","text":"Đúng vậy, tôi cần gấp lắm. Bao nhiêu tiền ship vậy?"},{"speaker":"salebot","text":"Giao trong ngày hôm nay chị nhé, phí ship 30.000đ thôi. Tổng cộng 629.000đ. Chị chọn phương thức thanh toán nào ạ?"},{"speaker":"client","text":"Chuyển khoản ngân hàng được không?"},{"speaker":"salebot","text":"Dạ được ạ! Em gửi link chuyển khoản qua tin nhắn cho chị nhé. Cảm ơn chị đã mua hàng!"}]','successs',4),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm mua một chiếc điện thoại giá tầm 5 triệu thôi. Có sản phẩm nào phù hợp không?"},{"speaker":"salebot","text":"Dạ, chào anh/chị! Với ngân sách 5 triệu, em giới thiệu chiếc **OPPO A17** ạ. Máy có màn hình 6.56 inch, pin 5000mAh, và camera chính 50MP, rất phù hợp cho nhu cầu hằng ngày ạ!"},{"speaker":"client","text":"Ồ, nghe hay đấy. Máy có màu gì vậy? Và giao hàng nhanh không?"},{"speaker":"salebot","text":"Dạ, em có đủ 3 màu: xanh dương, đen, vàng. Giao hàng trong 24h tại nội thành HN/HCM, miễn phí ship từ 2 triệu ạ. Anh/chị muốn đặt luôn không ạ?"},{"speaker":"client","text":"Được rồi, tôi chọn màu xanh dương. Bao lâu nhận được hàng vậy?"},{"speaker":"salebot","text":"Dạ, anh/chị sẽ nhận hàng vào chiều mai ạ! Em gửi kèm link thanh toán qua MoMo/VNPay, anh/chị có thể chọn phương thức ưng ý ạ. Cảm ơn anh/chị đã tin tưởng sản phẩm của em!"}]','successs',5),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm mua một chiếc điện thoại mới. Bạn có thể tư vấn cho tôi không?"},{"speaker":"salebot","text":"Chào bạn! Tôi rất vui được hỗ trợ. Bạn quan tâm đến dòng điện thoại nào? Tầm giá bao nhiêu?"},{"speaker":"client","text":"Tôi muốn một chiếc có camera tốt, tầm 15-20 triệu. Có mẫu nào giới thiệu không?"},{"speaker":"salebot","text":"Dạ, có ạ! Chiếc Samsung Galaxy A34 5G với camera 48MP, giá 16 triệu rất phù hợp. Bạn có muốn xem chi tiết không?"},{"speaker":"client","text":"Nghe ổn đấy. Tôi có thể mua online không? Giao hàng nhanh không?"},{"speaker":"salebot","text":"Dạ có ạ! Bạn chọn mua ngay sẽ được giao trong 2 giờ (nếu ở nội thành). Có ưu đãi giảm 5% cho đơn hàng đầu tiên. Bạn đặt luôn nhé?"},{"speaker":"client","text":"Ok, tôi chọn chiếc Galaxy A34 5G. Cảm ơn bạn nhé!"},{"speaker":"salebot","text":"Cảm ơn bạn đã mua hàng! Chúng tôi sẽ gửi mã giảm giá 5% qua email. Chúc bạn một ngày tốt lành!"}]','successs',6),
('[{"speaker":"client","text":"Tôi đang tìm một chiếc áo khoác mùa đông cho bé trai 5 tuổi, có màu sắc tươi sáng nhé."},{"speaker":"salebot","text":"Chào bạn! Cảm ơn vì đã quan tâm đến sản phẩm của chúng tôi. Hiện tại, chúng tôi có dòng áo khoác mùa đông cho bé trai với nhiều màu sắc tươi sáng như xanh dương, đỏ cam, vàng chanh. Bạn có thích màu nào không?"},{"speaker":"client","text":"Tôi thích màu xanh dương. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Áo khoác màu xanh dương cho bé trai 5 tuổi có giá 499.000đ. Bạn có muốn biết thêm về chất liệu hoặc kích thước không?"},{"speaker":"client","text":"Chất liệu thế nào? Có bền không?"},{"speaker":"salebot","text":"Chất liệu cotton pha polyester, thoáng khí và rất bền. Sản phẩm đã được kiểm định chất lượng trước khi xuất xưởng. Bạn có muốn đặt hàng không?"},{"speaker":"client","text":"Tôi không chắc lắm. Tôi sẽ suy nghĩ thêm nhé."}]','fail',7),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm mua một chiếc điện thoại mới. Bạn có thể giới thiệu cho tôi sản phẩm nào tốt không?"},{"speaker":"salebot","text":"Dạ vâng ạ! Hiện tại chúng tôi có sản phẩm điện thoại Samsung Galaxy A54 5G với giá 12 triệu, camera 50MP, pin trâu và màn hình siêu mượt. Bạn có nhu cầu gì đặc biệt không?"},{"speaker":"client","text":"Tôi không thích Samsung lắm, tôi nghe nói iPhone mới ra mắt có gì hay không?"},{"speaker":"salebot","text":"Dạ thưa anh/chị, hiện tại chúng tôi chưa nhập iPhone mới nhất, nhưng có iPhone 13 Pro 128GB giá 22 triệu ạ. Pin khỏe, chip mạnh, chụp ảnh đẹp lắm ạ!"},{"speaker":"client","text":"Tôi thấy giá hơi cao, tôi chỉ có 15 triệu thôi. Có sản phẩm nào ngon hơn không?"},{"speaker":"salebot","text":"Dạ thôi rồi ạ, nếu anh/chị có 15 triệu thì chỉ có thể mua iPhone 12 64GB hoặc Xiaomi Redmi Note 12 5G thôi ạ. Hay anh/chị xem qua mẫu Xiaomi đi ạ, cấu hình ngon lắm!"},{"speaker":"client","text":"Thế à, tôi không thích Xiaomi đâu. Thôi tôi đi xem nơi khác vậy. Cảm ơn bạn nhé!"}]','fail',8),
('[{"speaker":"client","text":"Chào bạn! Tôi đang tìm một chiếc điện thoại thông minh có camera tốt cho con gái tôi. Nó thích chụp ảnh lắm."},{"speaker":"salebot","text":"Chào chị! Tôi rất vui khi được hỗ trợ chị. Điện thoại nào chị đang quan tâm ạ? Tôi có thể gợi ý dòng iPhone 15 với camera 48MP siêu sắc nét, hoặc dòng Samsung Galaxy S23 với camera 12MP siêu rộng."},{"speaker":"client","text":"Con gái tôi thích chụp ảnh phong cảnh lắm, nên camera rộng có lẽ hợp hơn. Giá của hai dòng ấy khoảng bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ, dòng Samsung Galaxy S23 tầm 18 triệu, còn iPhone 15 tầm 22 triệu. Nếu chị mua trong hôm nay, tôi có thể giảm 500k cho chị ạ!"},{"speaker":"client","text":"Ồ, vậy thì tôi chọn Samsung Galaxy S23 nhé! Bao lâu thì giao hàng được?"},{"speaker":"salebot","text":"Dạ, giao hàng trong 2 giờ nếu chị ở TP.HCM, hoặc 1 ngày nếu ở tỉnh. Chị vui lòng cung cấp địa chỉ để tôi xử lý đơn hàng ạ?"}]','successs',9),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm một chiếc bàn học gỗ thông minh cho bé nhà mình. Có loại nào phù hợp không?"},{"speaker":"salebot","text":"Dạ chào chị! Em có ngay mẫu bàn học gỗ thông minh cho bé 6-12 tuổi, vừa có ngăn kéo đựng đồ vừa điều chỉnh độ cao linh hoạt. Chị thích màu gì ạ? Gỗ thông tự nhiên hay gỗ sồi?"},{"speaker":"client","text":"Mình thích màu gỗ tự nhiên, nhưng mà giá cả có hợp lý không? Mình sợ mua online không an toàn."},{"speaker":"salebot","text":"Dạ yên tâm ạ! Chị có thể thanh toán COD, chuyển khoản hoặc trả góp 0%. Sản phẩm được bảo hành 2 năm, giao miễn phí trong nội thành. Em gửi link chi tiết cho chị nhé?"},{"speaker":"client","text":"Ok, mình chọn màu gỗ thông nhé. Địa chỉ giao hàng là 123 Nguyễn Trãi, Quận 5, TP.HCM. Bao lâu thì nhận được hàng?"},{"speaker":"salebot","text":"Dạ chị ơi! Hàng giao trong 2-3 ngày làm việc. Em sẽ gửi mã theo dõi cho chị ngay sau khi xác nhận đơn. Cảm ơn chị đã tin tưởng ạ!"}]','successs',10),
('[{"speaker":"client","text":"Chào bạn! Tôi đang tìm kiếm một chiếc điện thoại mới để thay thế chiếc cũ đã dùng được 3 năm. Bạn có thể tư vấn giúp tôi không?"},{"speaker":"salebot","text":"Chào anh/chị! Rất vui được hỗ trợ. Anh/chị ưu tiên thương hiệu nào không ạ? Hoặc có nhu cầu về dung lượng pin, camera hay hiệu năng không?"},{"speaker":"client","text":"Tôi thích dòng iPhone nhưng ngại giá cao. Có sản phẩm nào vừa túi tiền vừa chất lượng không?"},{"speaker":"salebot","text":"Anh/chị có thể tham khảo iPhone 12 128GB, vừa đủ dùng, giá 15 triệu. Hoặc iPhone SE 2022 64GB giá 8 triệu nếu ngân sách hạn hẹp. Anh/chị có quan tâm không?"},{"speaker":"client","text":"Tôi thích iPhone 12. Bạn có thể giảm giá thêm không? Tôi thấy nhiều nơi bán rẻ hơn."},{"speaker":"salebot","text":"Anh/chị nhắn shop mình nhận ưu đãi 500k khi thanh toán qua ví MoMo. Tổng còn 14,5 triệu. Anh/chị đặt ngay không?"},{"speaker":"client","text":"Ok, tôi chọn iPhone 12 128GB. Bạn gửi link thanh toán đi!"},{"speaker":"salebot","text":"Cảm ơn anh/chị! Link thanh toán: [link]. Sau khi chuyển khoản, shop sẽ giao hàng trong 2h. Anh/chị có cần hướng dẫn sử dụng không?"}]','successs',11),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc điện thoại mới. Bạn có thể tư vấn giúp mình không?"},{"speaker":"salebot","text":"Chào bạn! Tất nhiên rồi ạ. Bạn đang tìm kiếm mẫu điện thoại nào? Mình có thể gợi ý những sản phẩm mới nhất, phù hợp với nhu cầu sử dụng của bạn."},{"speaker":"client","text":"Mình muốn một chiếc có camera tốt, pin khỏe và giá tầm dưới 10 triệu."},{"speaker":"salebot","text":"Vậy mình đề xuất chiếc [Tên sản phẩm] ạ! Máy có camera 50MP, pin 5000mAh, sạc nhanh 30W, giá chỉ 9.990.000đ. Đang có chương trình khuyến mại giảm 500k nếu đặt ngay hôm nay!"},{"speaker":"client","text":"Thế có giao hàng tận nơi không? Mình muốn nhận trong tuần này."},{"speaker":"salebot","text":"Hoàn toàn có ạ! Miễn phí ship nội thành cho đơn hàng trong hôm nay. Bạn chỉ cần để lại địa chỉ và số điện thoại, mình sẽ xử lý đơn hàng ngay!"},{"speaker":"client","text":"Ok, mình đặt luôn nhé! Cảm ơn bạn nhiều."},{"speaker":"salebot","text":"Cảm ơn bạn đã tin tưởng! Đơn hàng của bạn đã được ghi nhận. Chúng mình sẽ liên hệ trong vòng 30 phút để xác nhận. Chúc bạn một ngày vui vẻ!"}]','successs',12),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm mua một chiếc bàn làm việc để làm việc tại nhà. Bạn có thể giới thiệu sản phẩm cho tôi không?"},{"speaker":"salebot","text":"Chào chị! Tôi rất vui khi được hỗ trợ chị. Hiện chúng tôi có chiếc bàn làm việc bằng gỗ thông dụng, kích thước 120x60cm, giá chỉ 1.800.000đ. Nó rất phù hợp cho không gian làm việc tại nhà."},{"speaker":"client","text":"Ồ, nghe hay đấy. Nhưng tôi sợ gỗ thông không bền lắm. Bạn có loại nào bằng gỗ công nghiệp không?"},{"speaker":"salebot","text":"Dạ tất nhiên rồi chị! Chúng tôi có mẫu bàn bằng gỗ công nghiệp chống trầy xước, chịu lực tốt, giá 2.200.000đ. Nó vừa bền vừa dễ vệ sinh nữa."},{"speaker":"client","text":"Vậy thì tôi chọn mẫu đó đi. Có giao hàng tận nhà không? Tôi ở quận 7."},{"speaker":"salebot","text":"Dạ có chị ơi! Chúng tôi giao hàng miễn phí trong nội thành TP.HCM. Đơn hàng sẽ đến tay chị trong vòng 2-3 ngày làm việc. Chị vui lòng cung cấp địa chỉ và số điện thoại nhận hàng nhé?"},{"speaker":"client","text":"Cảm ơn bạn nhé! Tôi gửi địa chỉ: 123 đường Nguyễn Văn Linh, P.Tân Thuận Đông, Q.7. Số điện thoại: 0901234567."},{"speaker":"salebot","text":"Dạ cảm ơn chị đã tin tưởng mua hàng! Chúng tôi sẽ liên hệ xác nhận đơn hàng ngay. Chúc chị một ngày làm việc hiệu quả!"}]','successs',13),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm mua một chiếc đồng hồ thể thao cho bản thân. Bạn có thể giới thiệu cho tôi vài mẫu không?"},{"speaker":"salebot","text":"Dạ vâng ạ! Chúng tôi có mẫu đồng hồ thể thao **Casio G-Shock GA-2100** giá 1,2 triệu, siêu bền và chống nước tốt. Bạn có thích màu đen hay màu xanh không?"},{"speaker":"client","text":"Màu xanh thì sao? Tôi thích màu tươi sáng một chút."},{"speaker":"salebot","text":"Dạ màu xanh **GA-2100-1AER** hiện đang hết hàng ạ. Mẫu gần giống là **GA-2100-1B** màu xanh dương, anh chị có thể tham khảo nhé!"},{"speaker":"client","text":"Thế à... Tôi thấy màu này hơi tối, có màu sáng hơn không? Giá có thể cao hơn chút cũng được."},{"speaker":"salebot","text":"Dạ thưa anh chị, mẫu **Casio Edifice EFR-S571D-1A2V** màu trắng ngà, thiết kế sang trọng hơn, giá 2,8 triệu. Anh chị có muốn xem không?"},{"speaker":"client","text":"2,8 triệu à... Tôi nghĩ hơi đắt. Thôi để tôi suy nghĩ thêm rồi quay lại sau vậy. Cảm ơn bạn nhé!"}]','fail',14),
('[{"speaker":"client","text":"Chào bạn! Mình đang tìm mua một chiếc điện thoại mới. Bạn có thể giới thiệu cho mình một sản phẩm tốt không?"},{"speaker":"salebot","text":"Chào bạn! Rất vui được hỗ trợ. Bạn có nhu cầu gì đặc biệt không? Ví dụ như dung lượng pin lớn, màn hình chất lượng cao hay camera tốt?"},{"speaker":"client","text":"Mình muốn một chiếc điện thoại có camera tốt, pin trâu và giá phải chăng thôi. Bạn có gợi ý gì không?"},{"speaker":"salebot","text":"Tôi đề xuất chiếc **Xiaomi Redmi Note 12 Pro** nhé! Camera 108MP, pin 5000mAh, giá chỉ 6 triệu. Bạn có muốn xem chi tiết hơn không?"},{"speaker":"client","text":"Ừ, mình thích nó đấy! Có giảm giá gì không? Mình sợ tốn tiền quá."},{"speaker":"salebot","text":"Hiện tại có chương trình khuyến mại: giảm 500k khi mua kèm ốp lưng và giảm 20% phí ship. Bạn có muốn đặt ngay không?"},{"speaker":"client","text":"Ok, mình chọn màu đen nhé! Cảm ơn bạn nhiều."},{"speaker":"salebot","text":"Cảm ơn bạn đã mua hàng! Chúc bạn có trải nghiệm tuyệt vời với sản phẩm. Hẹn gặp lại!"}]','successs',15),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm mua một chiếc bàn học cho con trai tôi. Cháu học lớp 5, nên cần bàn vừa tầm. Bạn có sản phẩm gì phù hợp không?"},{"speaker":"salebot","text":"Chào anh/chị! Cảm ơn anh/chị đã quan tâm. Tôi giới thiệu đến anh/chị dòng bàn học thông minh có thể điều chỉnh chiều cao, vừa vặn với lứa tuổi lớp 5. Giá 2 triệu 500 ngàn, giao tận nhà miễn phí."},{"speaker":"client","text":"Ui, giá hơi cao so với dự định của tôi. Tôi định mua dưới 2 triệu thôi. Có sản phẩm nào rẻ hơn không?"},{"speaker":"salebot","text":"Dạ, anh/chị có thể tham khảo dòng bàn gỗ thông thường, giá 1 triệu 800 ngàn. Nhưng kích thước hơi nhỏ, chỉ phù hợp cho trẻ dưới 10 tuổi thôi ạ."},{"speaker":"client","text":"Ôi, cháu tôi cao hơn bạn bè cùng tuổi nên bàn nhỏ quá không vừa. Cảm ơn bạn nhé, tôi sẽ suy nghĩ thêm."}]','fail',16),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm mua một chiếc áo khoác mùa đông cho bé nhà mình. Bé trai 8 tuổi, cao 1m30. Có sản phẩm nào phù hợp không?"},{"speaker":"salebot","text":"Dạ chào anh/chị! Chúng tôi có dòng áo khoác chống gió, chống nước cho bé trai. Size 130-140 là vừa. Anh/chị muốn xem mẫu nào?"},{"speaker":"client","text":"Tôi muốn xem mẫu màu xanh dương, kiểu nhẹ nhàng thôi. Giá tầm bao nhiêu?"},{"speaker":"salebot","text":"Dạ mẫu áo khoác chống gió nhẹ nhàng màu xanh dương là 399.000đ. Có kèm mũ chống lạnh nữa ạ."},{"speaker":"client","text":"Ồ, hơi đắt quá. Tôi thấy trên mạng có nhiều mẫu 250k-300k. Có ưu đãi gì không?"},{"speaker":"salebot","text":"Dạ, ạ không biết ạ. Chúng tôi không có khuyến mại thêm ngoài giá niêm yết ạ. Anh/chị có thể tham khảo thêm mẫu khác ạ."}]','fail',17),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc bàn làm việc cho phòng ngủ nhỏ. Bạn có thể giới thiệu sản phẩm phù hợp không?"},{"speaker":"salebot","text":"Chào bạn! Mình rất vui được hỗ trợ. Phòng ngủ của bạn rộng khoảng bao nhiêu mét vuông vậy? Để mình tư vấn kích thước bàn hợp lý nhé."},{"speaker":"client","text":"Phòng mình khá nhỏ, chỉ khoảng 10m² thôi. Mình muốn bàn vừa gọn vừa có thể chứa đồ tiện lợi."},{"speaker":"salebot","text":"Vậy mình gợi ý bạn dòng bàn gấp gọn tiết kiệm không gian nhé! Đây là sản phẩm vừa được ưu đãi giảm giá 20%: Bàn gấp gọn 3 ngăn, kích thước 80x40cm, giá 1.200.000đ. Bạn có muốn xem chi tiết không?"},{"speaker":"client","text":"Ồ, giá hơi cao so với dự định của mình. Có sản phẩm nào rẻ hơn không?"},{"speaker":"salebot","text":"Mình hiểu rồi! Bạn tham khảo dòng bàn gấp đơn giản này nhé: Bàn gấp 2 ngăn, kích thước 70x35cm, giá 890.000đ. Chất liệu gỗ ép bền đẹp, phù hợp phòng nhỏ. Bạn có muốn đặt thử không?"},{"speaker":"client","text":"Ok, mình chọn sản phẩm 890k đi. Bao giờ giao được nhỉ?"},{"speaker":"salebot","text":"Cảm ơn bạn đã mua hàng! Sản phẩm sẽ giao trong 2-3 ngày làm việc. Mình gửi link thanh toán qua ZaloPay nhé. Bạn có cần hỗ trợ thêm gì không?"}]','successs',18),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm mua một chiếc áo khoác cho mùa đông này. Giá tầm 1 triệu thôi nhé."},{"speaker":"salebot","text":"Chào chị ạ! Em có ngay bộ sưu tập áo khoác mùa đông từ 800k đến 1.5 triệu. Chị thích kiểu dáng nào ạ? Cổ tròn, cổ bẻ hay có mũ?"},{"speaker":"client","text":"Tôi thích kiểu cổ bẻ, nhưng màu sắc thì... chắc phải đợi chồng tôi xem. Anh ấy bảo màu tối quá thì không hợp."},{"speaker":"salebot","text":"Dạ, em hiểu ạ! Chị cứ yên tâm, em sẽ gửi link kèm ảnh mẫu cho chị tham khảo. Nếu chồng chị thích thì chị đặt ngay cũng được ạ!"},{"speaker":"client","text":"Thế à? Hay quá! Nhưng... tôi thấy trên mạng nhiều chỗ bán rẻ hơn. Có đảm bảo chất lượng không?"},{"speaker":"salebot","text":"Dạ, em xin lỗi vì sự bất tiện này ạ! Chị có thể check review từ khách hàng cũ trên web của em. Chất liệu 100% cotton, may tại Việt Nam nên rất bền chị nhé."},{"speaker":"client","text":"À, thôi tôi nghĩ để tôi suy nghĩ thêm. Cảm ơn bạn nhé!"}]','fail',19),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc áo khoác nam cho mùa đông này. Bạn có thể giới thiệu sản phẩm nào tốt không?"},{"speaker":"salebot","text":"Chào anh! Em rất vui khi được hỗ trợ. Hiện tại shop mình có dòng áo khoác chống gió chống thấm hiệu quả, giá từ 890.000đ. Anh muốn xem sản phẩm nào trước ạ?"},{"speaker":"client","text":"Mình thích màu đen thôi. Nhưng giá hơi cao quá, có chương trình giảm giá nào không?"},{"speaker":"salebot","text":"Dạ, hôm nay shop có ưu đãi 10% cho đơn hàng đầu tiên. Kèm theo quà tặng là một chiếc khăn len trị giá 150.000đ nữa ạ!"},{"speaker":"client","text":"Ừm... mình cân nhắc lại đã. Thôi không mua nữa, tạm biệt nhé!"}]','fail',20),
('[{"speaker":"client","text":"Anh ơi, em thấy cái bàn chải điện này có mẫu đẹp nhưng giá hơi cao so với túi tiền của em. Có cách nào giảm giá không?"},{"speaker":"salebot","text":"Chào chị! Em xin lỗi vì giá sản phẩm hơi cao so với mong đợi của chị. Hiện tại shop đang có chương trình giảm 10% cho đơn hàng trên 500k, chị có thể tham khảo thêm sản phẩm khác để đạt đủ điều kiện nhé!"},{"speaker":"client","text":"Em không mua thêm đâu, em chỉ cần cái bàn chải điện này thôi. Nếu không giảm giá thì em sẽ nghĩ lại vậy."},{"speaker":"salebot","text":"Em thật sự xin lỗi vì không thể đáp ứng yêu cầu của chị. Chúc chị có một ngày tốt lành nhé!"}]','fail',21),
('[{"speaker":"client","text":"Anh ơi, em đang tìm cái túi xách da này cho chị mình. Chị ấy thích kiểu đơn giản nhưng chất lượng tốt ấy. Anh tư vấn giúp em với!"},{"speaker":"salebot","text":"Dạ, em xin lỗi chị ơi! Túi xách da kiểu đơn giản chất lượng tốt thì em xin giới thiệu mẫu này ạ. Được làm từ da thật 100%, màu nâu nhạt rất sang trọng. Giá chỉ 1.290.000đ thôi ạ!"},{"speaker":"client","text":"Ôi, giá hơi cao quá anh ơi. Em định chi khoảng 800k thôi ấy. Có mẫu nào rẻ hơn không?"},{"speaker":"salebot","text":"Dạ, em xin lỗi chị ạ. Mẫu rẻ hơn thì em có mẫu này 590.000đ, nhưng da giả thôi chị nhé. Chị có thể cân nhắc ạ!"},{"speaker":"client","text":"À, em thấy mẫu da giả cũng được. Nhưng em không chắc chị em có thích không nữa. Thôi em suy nghĩ thêm nhé. Cảm ơn anh nhé!"}]','fail',22),
('[{"speaker":"client","text":"Tôi đang tìm kiếm một chiếc điện thoại thông minh giá tầm 5 triệu thôi, có salebot nào tư vấn giúp tôi không?"},{"speaker":"salebot","text":"Dạ vâng ạ! Em có thể gợi ý cho chị một số mẫu điện thoại tầm 5 triệu như Xiaomi Redmi Note 11 hoặc Samsung Galaxy A03s ạ. Chị thích dòng nào ạ?"},{"speaker":"client","text":"Tôi thấy mẫu Samsung Galaxy A03s có vẻ ổn. Nhưng tôi nghe nói nó chậm lắm, đúng không?"},{"speaker":"salebot","text":"Dạ, em xin lỗi vì thông tin chưa rõ ràng ạ. Galaxy A03s dùng chip thấp nên chạy hơi chậm khi mở nhiều ứng dụng cùng lúc. Nếu chị muốn mượt hơn, em có thể giới thiệu chị mẫu Redmi Note 11 với chip mạnh hơn 1 chút, giá cũng chỉ hơn 1 chút thôi ạ!"},{"speaker":"client","text":"Thế à... Tôi thì không thích mấy hãng Trung Quốc lắm. Cảm ơn salebot nhé, tôi sẽ tìm hiểu thêm!"}]','fail',23),
('[{"speaker":"client","text":"Chào bạn! Tôi đang tìm mua một chiếc bàn học gỗ cho con gái tôi. Nó vừa vào lớp 1, cần bàn học chắc chắn và an toàn."},{"speaker":"salebot","text":"Chào chị! Cảm ơn chị đã quan tâm đến sản phẩm của chúng tôi. Chúng tôi có bàn học gỗ thông minh với khung chắc chắn, chống cong vênh, an toàn cho trẻ em. Chị muốn kích thước bao nhiêu ạ?"},{"speaker":"client","text":"À, tôi chưa rõ lắm. Chiếc bàn dài khoảng 1m2 là được rồi. Màu sắc thì có gì nhỉ?"},{"speaker":"salebot","text":"Dạ, chúng tôi có 3 màu: trắng sữa, gỗ tự nhiên và xanh dương nhạt. Màu trắng sữa rất phổ biến vì dễ kết hợp với mọi không gian. Chị thích màu nào nhất?"},{"speaker":"client","text":"Tôi thích màu trắng sữa nhưng giá cả thế nào? Tôi thấy hơi lo lắng về chi phí."},{"speaker":"salebot","text":"Dạ, giá bàn học gỗ trắng sữa loại này là 1.290.000đ, đã bao gồm VAT. Đặc biệt tuần này có ưu đãi giảm 10% nếu chị đặt ngay."},{"speaker":"client","text":"1.290.000đ à? Tôi nghĩ hơi đắt so với túi tiền hiện tại. Có thể giảm thêm không?"},{"speaker":"salebot","text":"Dạ, chúng tôi đã giảm giá nhiều nhất rồi ạ. Nếu chị không ưng, tôi có thể giới thiệu loại bàn gỗ ép giá rẻ hơn 890.000đ nhưng chất liệu kém hơn."},{"speaker":"client","text":"Thế thì thôi vậy. Cảm ơn bạn nhiều nhé. Tôi sẽ suy nghĩ thêm."}]','fail',24),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm mua một chiếc bàn làm việc gỗ cho phòng khách. Bạn có thể giới thiệu sản phẩm nào phù hợp không?"},{"speaker":"salebot","text":"Chào anh/chị ạ! Tôi rất vui khi được hỗ trợ. Hiện tại chúng tôi đang có bàn làm việc gỗ óc chó kích thước 120x60cm, màu nâu tự nhiên rất sang trọng. Điểm nổi bật là mặt bàn chống trầy xước và khung thép chịu lực, giá chỉ 2.590.000đ thôi ạ!"},{"speaker":"client","text":"Ồ, giá hơi cao so với dự tính. Có sản phẩm nào rẻ hơn không?"},{"speaker":"salebot","text":"Dạ anh/chị có thể tham khảo bàn gỗ công nghiệp 100x50cm giá 1.790.000đ. Mẫu này cũng bền và dễ vệ sinh lắm ạ. Hoặc nếu anh/chị muốn tiết kiệm hơn nữa, có bàn gỗ ghép 80x40cm giá 990.000đ."},{"speaker":"client","text":"Thế bàn gỗ óc chó có giảm giá không? Tôi thích mẫu đó nhưng ngại giá."},{"speaker":"salebot","text":"Dạ, hôm nay chúng tôi có chương trình khuyến mại 10% cho sản phẩm gỗ óc chó nếu anh/chị đặt ngay hôm nay ạ! Và giao hàng miễn phí trong nội thành. Anh/chị thấy thế nào?"},{"speaker":"client","text":"Ok, tôi chọn bàn gỗ óc chó vậy. Bao giờ giao được?"},{"speaker":"salebot","text":"Dạ, anh/chị vui lòng cung cấp địa chỉ nhận hàng và số điện thoại để chúng tôi xác nhận đơn hàng ạ. Thời gian giao hàng dự kiến trong 3-5 ngày làm việc."}]','successs',25),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm mua một chiếc điện thoại mới, có thể tư vấn giúp tôi không?"},{"speaker":"salebot","text":"Chào bạn! Tôi rất vui được hỗ trợ. Bạn có nhu cầu gì cụ thể về điện thoại không? Ví dụ như dung lượng pin, camera hay hiệu năng?"},{"speaker":"client","text":"Tôi muốn một chiếc điện thoại có camera tốt, dung lượng pin lớn và giá tầm 10-12 triệu thôi."},{"speaker":"salebot","text":"Tôi gợi ý bạn chiếc Xiaomi Redmi Note 12 Pro, camera 108MP, pin 5000mAh, giá chỉ 11 triệu. Bạn có quan tâm không?"},{"speaker":"client","text":"Nghe ổn đấy, tôi có thể mua online không? Có giao hàng tận nơi không?"},{"speaker":"salebot","text":"Có chứ ạ! Bạn chỉ cần chọn phương thức thanh toán (tiền mặt hay chuyển khoản) và địa chỉ nhận hàng, chúng tôi sẽ giao tận nơi trong 2-3 ngày."},{"speaker":"client","text":"Tuyệt vời, tôi sẽ chọn chuyển khoản. Cảm ơn bạn nhé!"},{"speaker":"salebot","text":"Cảm ơn bạn đã mua hàng! Chúc bạn có trải nghiệm tuyệt vời với sản phẩm. Hẹn gặp lại!"}]','successs',26),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm kiếm một chiếc bàn học cho con gái tôi. Nó 12 tuổi, thích màu hồng và có thể điều chỉnh độ cao. Có gì gợi ý không?"},{"speaker":"salebot","text":"Chào chị! Rất vui được hỗ trợ. Chúng tôi có bàn học màu hồng với khả năng điều chỉnh độ cao từ 60-120cm, phù hợp với lứa tuổi của bé. Giá thành 1.590.000đ, chị có muốn xem ảnh sản phẩm không?"},{"speaker":"client","text":"À, giá hơi cao so với dự định. Tôi chỉ định mua dưới 1 triệu thôi. Có bàn nào khác không?"},{"speaker":"salebot","text":"Chị thông cảm, sản phẩm này có nhiều tính năng cao cấp nên giá hơi cao. Chúng tôi cũng có bàn đơn giản hơn giá 850.000đ, nhưng không điều chỉnh được độ cao. Chị xem thử nhé?"},{"speaker":"client","text":"Thế không được rồi. Con tôi cần bàn có thể điều chỉnh để lớn lên vẫn dùng được. Cảm ơn bạn nhé!"}]','fail',27),
('[{"speaker":"client","text":"Mình đang tìm một chiếc áo khoác mùa đông cho bé trai 5 tuổi, nhưng không biết chọn loại nào phù hợp nữa."},{"speaker":"salebot","text":"Chào bạn! Mình có áo khoác ấm cho bé trai 5 tuổi, có nhiều màu sắc và chất liệu cotton thoáng khí. Bạn muốn xem sản phẩm nào trước ạ?"},{"speaker":"client","text":"Mình lo lắm, bé nhà mình hay chạy nhảy nên sợ áo dày quá không thoải mái. Có loại nào nhẹ nhàng nhưng vẫn giữ ấm không?"},{"speaker":"salebot","text":"Dạ, chúng mình có mẫu áo khoác lông cừu siêu nhẹ, vừa giữ ấm vừa thoáng khí. Giá tầm 450k, bạn xem thử có hợp không?"},{"speaker":"client","text":"450k hơi đắt so với mình nghĩ. Mình tìm nơi khác giá rẻ hơn thôi, cảm ơn bạn nhé!"}]','fail',28),
('[{"speaker":"client","text":"Chào bạn! Tôi muốn mua một chiếc điện thoại thông minh. Bạn có sản phẩm nào mới và chất lượng không?"},{"speaker":"salebot","text":"Chào bạn! Hiện chúng tôi đang có chương trình khuyến mại siêu hot về dòng điện thoại Samsung Galaxy S23 Ultra 5G. Bạn quan tâm dòng sản phẩm này không?"},{"speaker":"client","text":"Ừ, tôi thấy nó khá ổn. Giá bao nhiêu vậy? Có khuyến mại gì không?"},{"speaker":"salebot","text":"Dạ, giá niêm yết là 25 triệu, nhưng trong chương trình hôm nay, bạn sẽ được giảm còn 22 triệu kèm theo quà tặng là tai nghe không dây trị giá 2 triệu. Bạn có muốn đặt mua không?"},{"speaker":"client","text":"Thế giao hàng miễn phí chứ? Tôi không muốn phải trả thêm phí vận chuyển."},{"speaker":"salebot","text":"Dạ, tất nhiên rồi! Chúng tôi giao hàng miễn phí trong nội thành Hà Nội. Bạn có thể thanh toán bằng tiền mặt hay chuyển khoản đều được ạ."},{"speaker":"client","text":"Ok, vậy tôi đặt luôn chiếc này đi. Bao lâu thì nhận được hàng vậy?"},{"speaker":"salebot","text":"Dạ, đơn hàng của bạn sẽ được giao trong vòng 24-48 giờ. Bạn vui lòng cung cấp địa chỉ và số điện thoại để chúng tôi liên hệ nhé!"}]','successs',29),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm mua một chiếc bàn học cho con gái tôi. Nó mới vào lớp 1, nên cần bàn vừa vặn với chiều cao của bé. Bạn có thể tư vấn giúp tôi không?"},{"speaker":"salebot","text":"Chào chị! Cảm ơn chị đã quan tâm đến sản phẩm của chúng tôi. Chúng tôi có dòng bàn học điều chỉnh độ cao cho trẻ em, phù hợp với lứa tuổi lớp 1. Bạn có thể xem qua mẫu này: [link sản phẩm]."},{"speaker":"client","text":"Ồ, sản phẩm nhìn ổn đấy. Nhưng tôi thấy giá hơi cao so với ngân sách của mình. Có sản phẩm nào rẻ hơn không?"},{"speaker":"salebot","text":"Dạ, chúng tôi cũng có bàn học gỗ không điều chỉnh độ cao, giá chỉ 890.000đ. Chất liệu gỗ công nghiệp cao cấp, an toàn cho bé. Bạn có muốn xem ảnh không?"},{"speaker":"client","text":"Cảm ơn, nhưng tôi nghĩ tôi sẽ suy nghĩ thêm. Hiện tại tôi chưa quyết định được."}]','fail',30),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm mua một chiếc áo khoác mùa đông cho bé gái 5 tuổi. Có gì gợi ý không?"},{"speaker":"salebot","text":"Chào chị ạ! Em có ngay sản phẩm phù hợp: Áo khoác chống gió, có mũ, màu hồng nhạt, giá 350.000đ. Chị có muốn xem ảnh mẫu không?"},{"speaker":"client","text":"Màu sắc thì được, nhưng giá hơi cao so với dự định. Có sản phẩm khác rẻ hơn không?"},{"speaker":"salebot","text":"Dạ, em có mẫu khác giá 220.000đ nhưng chất liệu kém hơn, không chống nước. Chị muốn thử không?"},{"speaker":"client","text":"Thôi vậy, tôi nghĩ sẽ mua sau. Cảm ơn nhé!"}]','fail',31),
('[{"speaker":"client","text":"Chào bạn! Tôi đang tìm một chiếc áo khoác mùa đông ấm áp, nhưng nhìn chung nó không quá đắt. Bạn có gợi ý gì không?"},{"speaker":"salebot","text":"Chào chị! Tôi rất vui khi giúp chị nhé. Hiện tại shop chúng tôi đang có mẫu áo khoác dạ chống lạnh giá 599.000đ, chất liệu siêu mềm mại và có lớp chống gió. Chị có muốn xem ảnh hoặc mẫu không?"},{"speaker":"client","text":"Ồ, nghe hay đấy! Tôi có thể thử size M được không? Tôi cao 1m65, cân nặng 58kg."},{"speaker":"salebot","text":"Dạ tất nhiên rồi chị ơi! Size M của mẫu này vừa vặn với chị đó. Nếu chị muốn, shop có chính sách đổi trả miễn phí trong 7 ngày. Chị có muốn đặt luôn không?"},{"speaker":"client","text":"Tuyệt! Tôi chọn màu đen nhé. Cảm ơn bạn nhiều!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Chúc chị có trải nghiệm mua sắm vui vẻ. Chị vui lòng cung cấp địa chỉ giao hàng để shop xử lý đơn hàng nhé!"}]','successs',32),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm mua một chiếc bàn học gỗ cho con gái tôi. Cháu ấy học lớp 3, cần bàn vừa vặn. Bạn có thể tư vấn giúp tôi không?"},{"speaker":"salebot","text":"Dạ chào cô ạ! Tôi rất vui khi được hỗ trợ cô. Chúng tôi có bàn học gỗ thông minh cho bé, kích thước 120x60cm, có ngăn kéo đựng đồ. Giá 1.890.000đ, bảo hành 2 năm. Cô có muốn xem ảnh sản phẩm không ạ?"},{"speaker":"client","text":"Ồ, nghe hay đấy! Tôi có thể xem ảnh được không? Giá cả có ổn không?"},{"speaker":"salebot","text":"Dạ vâng ạ! Đây là link ảnh sản phẩm: [link]. Giá này đã bao gồm phí vận chuyển toàn quốc. Nếu cô mua trong hôm nay, tôi có thể giảm 5% cho cô ạ!"},{"speaker":"client","text":"Tuyệt quá! Tôi sẽ mua ngay. Làm thế nào để thanh toán và giao hàng vậy?"},{"speaker":"salebot","text":"Dạ cô vui lòng chọn phương thức thanh toán: chuyển khoản ngân hàng hoặc COD. Sau khi thanh toán xong, đơn hàng sẽ giao trong 2-3 ngày. Cô có thể để lại số điện thoại và địa chỉ nhận hàng không ạ?"},{"speaker":"client","text":"Tôi chọn COD nhé. Địa chỉ là 123 Đường Lê Lợi, Phường 5, Quận 3, TP.HCM. Số điện thoại 0901234567. Cảm ơn bạn nhiều!"},{"speaker":"salebot","text":"Dạ cảm ơn cô đã tin tưởng sản phẩm của chúng tôi! Đơn hàng #20240615 của cô đã được ghi nhận. Chúc cô một ngày tốt lành!"}]','successs',33),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm mua một chiếc điện thoại mới. Bạn có thể tư vấn giúp tôi không?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Em có thể hỗ trợ anh/chị tìm điện thoại phù hợp. Anh/chị quan tâm dòng nào nhất: phổ thông, gaming, hay camera đẹp ạ?"},{"speaker":"client","text":"Tôi chỉ cần dùng cơ bản thôi, không chơi game hay chụp ảnh chuyên nghiệp. Giá tầm 5-7 triệu là được."},{"speaker":"salebot","text":"Dạ, em giới thiệu anh/chị mẫu [Tên sản phẩm] ạ. Cấu hình ổn định, pin trâu, giá 6.990.000đ. Anh/chị có muốn xem ảnh hay thông số chi tiết không ạ?"},{"speaker":"client","text":"ThếDelivery nhanh không? Tôi cần gấp lắm."},{"speaker":"salebot","text":"Dạ, em xin lỗi ạ. Hiện tại sản phẩm này đang hết hàng tạm thời. Anh/chị có thể để lại số điện thoại để em thông báo khi có hàng mới không ạ?"},{"speaker":"client","text":"Thôi, tôi đợi sau vậy. Cảm ơn nhé!"}]','fail',34),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm mua một chiếc bàn học cho con gái tôi. Nó học lớp 5 thôi, nhưng bàn cần chắc chắn và thoải mái."},{"speaker":"salebot","text":"Chào chị! Cảm ơn chị đã quan tâm đến sản phẩm của chúng tôi. Chị muốn bàn học có kích thước bao nhiêu? Hay có tính năng đặc biệt nào không ạ?"},{"speaker":"client","text":"Chị không biết nhiều về bàn học lắm. Chỉ cần chắc chắn, màu sắc nhẹ nhàng thôi. Giá khoảng 1 triệu đến 1,5 triệu thôi nhé."},{"speaker":"salebot","text":"Dạ vâng chị, chúng tôi có bàn gỗ ép chống cong vênh, màu trắng sữa, giá 1,2 triệu. Chị có muốn xem ảnh mẫu không ạ?"},{"speaker":"client","text":"À, chị thấy bàn hơi nhỏ so với mong đợi. Chị định mua bàn cho bé gái 10 tuổi cơ mà. Có bàn lớn hơn không?"},{"speaker":"salebot","text":"Dạ, chúng tôi có bàn kích thước 120x60cm, giá 1,8 triệu. Có thể điều chỉnh chiều cao nữa ạ."},{"speaker":"client","text":"Ồ, vậy à. Nhưng giá hơi cao so với dự định. Chị sẽ suy nghĩ thêm. Cảm ơn bạn nhé!"}]','fail',35),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm mua một chiếc điện thoại mới. Bạn có thể giới thiệu sản phẩm tốt nhất hiện nay không?"},{"speaker":"salebot","text":"Chào bạn! Tôi rất vui khi được hỗ trợ. Hiện tại, chiếc điện thoại Samsung Galaxy S23 Ultra đang được ưa chuộng nhất với camera 200MP, giá chỉ 22 triệu. Bạn có quan tâm không?"},{"speaker":"client","text":"Wow, giá hơi cao so với ngân sách của tôi. Có sản phẩm nào tầm 15 triệu không?"},{"speaker":"salebot","text":"Dạ, vậy bạn có thể xem qua Xiaomi Redmi Note 12 Pro+ 5G nhé! Máy có màn hình AMOLED 120Hz, pin 5000mAh, giá 14.99 triệu. Đang khuyến mại giảm 10% nữa đó!"},{"speaker":"client","text":"Tuyệt quá! Tôi sẽ mua ngay. Bạn có thể ship hàng trong ngày không?"},{"speaker":"salebot","text":"Dạ có ạ! Bạn vui lòng cung cấp địa chỉ và số điện thoại để tôi xác nhận đơn hàng nhé. Cảm ơn bạn đã mua sắm cùng chúng tôi!"}]','successs',36),
('[{"speaker":"client","text":"Chào bạn! Tôi đang tìm mua một chiếc áo khoác mùa đông cho bé gái 5 tuổi, nhưng giá cả có hơi đắt so với túi tiền của tôi."},{"speaker":"salebot","text":"Chào chị! Tôi hiểu ạ, nhưng sản phẩm này được làm từ chất liệu chống thấm gió, rất ấm và an toàn cho bé. Có mẫu giá 399.000đ chị nhé?"},{"speaker":"client","text":"399k vẫn hơi cao quá, tôi chỉ có 300k thôi. Có mẫu nào rẻ hơn không?"},{"speaker":"salebot","text":"Dạ, mẫu cơ bản hơn giá 299.000đ nhưng chất liệu kém hơn 1 chút. Hay chị để tôi gửi link ưu đãi 10% cho lần mua đầu tiên nhé?"},{"speaker":"client","text":"Thôi cũng được, nhưng tôi cần giao trong tuần này. Có đảm bảo không?"},{"speaker":"salebot","text":"Dạ có ạ! Shop cam kết giao trong 3-5 ngày. Chị cứ đặt đi, nếu không vừa thì đổi trả miễn phí trong 7 ngày."},{"speaker":"client","text":"Thôi thôi, tôi suy nghĩ lại rồi. Cảm ơn nhé!"}]','fail',37),
('[{"speaker":"client","text":"Chào bạn! Mình đang tìm mua một chiếc laptop để học tập và làm việc tại nhà. Bạn có thể tư vấn giúp mình không?"},{"speaker":"salebot","text":"Chào bạn nha! Mình rất vui khi được tư vấn cho bạn. Bạn có nhu cầu về cấu hình hay ngân sách cụ thể không? Mình sẽ gợi ý sản phẩm phù hợp nhất!"},{"speaker":"client","text":"Mình cần laptop mỏng nhẹ, pin tốt, giá dưới 15 triệu. Mình thích dòng Lenovo ThinkPad nhưng không biết có mẫu nào phù hợp không?"},{"speaker":"salebot","text":"Dạ, mình có mẫu Lenovo ThinkPad E14 Gen 4 với giá chỉ 14,5 triệu, chip Intel Core i5, RAM 8GB, SSD 512GB. Pin có thể lên đến 8 tiếng sử dụng. Bạn xem có ưng không?"},{"speaker":"client","text":"Nghe ổn đó! Mình có thể thanh toán online không? Và giao hàng trong bao lâu?"},{"speaker":"salebot","text":"Dạ được chứ! Bạn chọn thanh toán qua MoMo, VNPay hay chuyển khoản ngân hàng đều được. Giao hàng tận nơi trong 2-3 ngày làm việc. Bạn muốn đặt hàng luôn không?"},{"speaker":"client","text":"Ok, mình đặt luôn đi! Cảm ơn bạn nhiều nha!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Cảm ơn bạn đã mua hàng. Chúc bạn một ngày tốt lành!"}]','successs',38),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc điện thoại mới. Bạn có thể tư vấn cho mình không?"},{"speaker":"salebot","text":"Chào bạn! Tất nhiên rồi. Bạn quan tâm dòng điện thoại nào? Mình có thể gợi ý dòng iPhone 15 Pro Max, Samsung Galaxy S24 Ultra hoặc Xiaomi 14 Pro. Bạn thích kiểu dáng nào?"},{"speaker":"client","text":"Mình thích thiết kế sang trọng, màn hình lớn và camera tốt. Giá tầm 20-25 triệu là được."},{"speaker":"salebot","text":"Vậy mình đề xuất Xiaomi 14 Pro nhé! Giá chỉ 22 triệu, màn hình 6.73 inches AMOLED, camera 50MP, pin 4880mAh. Bạn có muốn mình gửi link đặt hàng không?"},{"speaker":"client","text":"Ừ, mình thích lắm. Bao giờ giao được?"},{"speaker":"salebot","text":"Đơn hàng sẽ giao trong 2-3 ngày làm việc. Bạn có muốn thanh toán qua VNPay hay COD nhỉ?"},{"speaker":"client","text":"Mình chọn thanh toán online nhé. Cảm ơn bạn nhiều!"}]','successs',39),
('[{"speaker":"client","text":"Chào bạn! Tôi đang tìm mua một chiếc bàn làm việc mới. Bạn có thể giới thiệu sản phẩm cho tôi không?"},{"speaker":"salebot","text":"Chào bạn! Tôi rất vui được hỗ trợ. Bạn ưa thích kiểu dáng nào? Gỗ, kim loại hay hiện đại?"},{"speaker":"client","text":"Tôi thích kiểu dáng hiện đại, gọn nhẹ. Kích thước khoảng 120x60cm là vừa phải."},{"speaker":"salebot","text":"Tôi có ngay sản phẩm phù hợp: Bàn làm việc hiện đại bằng gỗ công nghiệp, kích thước 120x60cm, màu nâu nhạt. Giá 2.500.000đ, giao hàng miễn phí trong 2 ngày."},{"speaker":"client","text":"Nghe ổn đấy! Tôi có thể thanh toán online không?"},{"speaker":"salebot","text":"Dạ có! Bạn có thể thanh toán qua MoMo, VNPay hoặc chuyển khoản ngân hàng. Sau khi thanh toán, tôi sẽ gửi mã vận đơn qua Zalo/SMS."},{"speaker":"client","text":"Tuyệt! Tôi chọn thanh toán qua MoMo. Đợi tôi 5 phút nhé."}]','successs',40),
('[{"speaker":"client","text":"Mình đang tìm một chiếc áo khoác mùa đông cho bé gái 5 tuổi. Có gì gợi ý không?"},{"speaker":"salebot","text":"Chào bạn! Chúng tôi có sẵn mẫu áo khoác ấm bằng vải chống nước, màu hồng và xanh dương, giá 399k. Bạn muốn xem ảnh chi tiết không?"},{"speaker":"client","text":"Ừ, gửi ảnh đi. Nhưng mình nghe nói loại này hay bị bung chỉ sau vài lần giặt?"},{"speaker":"salebot","text":"Dạ không ạ, sản phẩm được may từ chất liệu chống xước và chỉ may kép, đảm bảo bền lâu. Bạn có thể yên tâm nhé!"},{"speaker":"client","text":"Thế giao hàng bao lâu vậy? Mình cần gấp lắm."},{"speaker":"salebot","text":"Dạ, giao trong 3-5 ngày. Nhưng hiện tại size 5 tuổi đã hết hàng rồi ạ. Bạn có thể chọn size 6 tuổi không?"},{"speaker":"client","text":"Ôi thế à... size 6 tuổi thì bé mặc rộng quá. Thôi mình bỏ qua vậy. Cảm ơn nhé!"}]','fail',41),
('[{"speaker":"client","text":"Mình đang tìm một chiếc áo sơ mi nữ cho buổi họp quan trọng tuần tới. Bạn có gợi ý gì không?"},{"speaker":"salebot","text":"Chào bạn! Mình có áo sơ mi nữ chất liệu cotton thoáng mát, màu xanh navy sang trọng. Bạn muốn size nào?"},{"speaker":"client","text":"Size M thôi. Nhưng màu xanh navy hơi tối, mình thích màu pastel hơn. Có màu gì vậy?"},{"speaker":"salebot","text":"Hiện tại mình chỉ có màu xanh navy, trắng và hồng nhạt thôi ạ. Bạn có thể chọn màu hồng nhạt nhé?"},{"speaker":"client","text":"Mình không thích hồng. Thôi vậy, mình xem shop khác vậy. Cảm ơn!"}]','fail',42),
('[{"speaker":"client","text":"Chào em, mình đang tìm mua một đôi giày thể thao nam cho anh trai mình. Anh ấy thích màu đen và kích cỡ 42. Có gì hay không?"},{"speaker":"salebot","text":"Chào anh/chị ạ! Em có ngay đôi giày thể thao nam màu đen, size 42 của thương hiệu Nike vừa nhập về. Giá 1.299.000đ, anh/chị có muốn xem ảnh mẫu không?"},{"speaker":"client","text":"Ồ, giá hơi cao so với dự định của mình. Có loại nào rẻ hơn không? Khoảng 800k thôi ấy."},{"speaker":"salebot","text":"Em xin lỗi ạ, sản phẩm tầm 800k thường là hàng kém chất lượng hoặc size không đủ. Em có thể giới thiệu đôi Adidas size 42 giá 999.000đ, vừa bền vừa đẹp ạ!"},{"speaker":"client","text":"Thế à... Chà, mình nghĩ mình sẽ cân nhắc thêm. Cảm ơn em nhé!"}]','fail',43),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc áo khoác chống thấm cho mùa đông này. Bạn có thể giới thiệu sản phẩm phù hợp không?"},{"speaker":"salebot","text":"Chào bạn! Mình rất vui khi được hỗ trợ. Hiện tại chúng tôi có dòng áo khoác chống thấm *SnowMaster Pro* với lớp phủ chống nước 10.000mmH₂O, rất phù hợp cho mùa đông lạnh giá. Bạn muốn màu sắc hay kích thước nào?"},{"speaker":"client","text":"Mình thích màu đen, kích thước M. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Áo *SnowMaster Pro* màu đen size M đang có giá 1.290.000đ, kèm theo khuyến mãi miễn phí giao hàng trong 24h nếu đặt ngay hôm nay!"},{"speaker":"client","text":"Tuyệt quá! Mình quyết định mua luôn. Bạn hướng dẫn mình thanh toán nhé."},{"speaker":"salebot","text":"Cảm ơn bạn đã tin tưởng! Bạn vui lòng chọn phương thức thanh toán: chuyển khoản ngân hàng, ví điện tử (MoMo/VNPay) hay thanh toán khi nhận hàng đều được ạ."}]','successs',44),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc áo thể thao cho bé gái 5 tuổi. Bạn có sản phẩm nào phù hợp không?"},{"speaker":"salebot","text":"Chào chị, cảm ơn chị đã quan tâm! Chúng tôi có áo thể thao cho bé gái, giá từ 250.000đ đến 450.000đ. Chị muốn kích cỡ nào ạ?"},{"speaker":"client","text":"Mình muốn size 5-6 tuổi thì sao? Bé nhà mình hơi gầy tí, nên mình muốn chọn size rộng hơn."},{"speaker":"salebot","text":"Dạ size 5-6 tuổi thì bé mặc vừa vặn ạ. Nếu chị muốn rộng hơn, chúng tôi có size 7-8 tuổi nhưng có thể hơi rộng. Chị có muốn xem ảnh sản phẩm không ạ?"},{"speaker":"client","text":"Thôi, mình không chắc lắm. Mình sẽ suy nghĩ thêm rồi quay lại sau nhé. Cảm ơn bạn!"},{"speaker":"salebot","text":"Dạ không sao ạ. Chúc chị ngày mới vui vẻ! Nếu cần hỗ trợ gì thêm, chị cứ quay lại nhé."}]','fail',45),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm mua một chiếc áo khoác mùa đông. Bạn có sản phẩm nào phù hợp không?"},{"speaker":"salebot","text":"Dạ vâng ạ! Chúng tôi có nhiều mẫu áo khoác mùa đông từ các thương hiệu uy tín. Bạn ưng màu nào nhất? Màu đen, xám hay xanh dương?"},{"speaker":"client","text":"Tôi thích màu đen nhưng không chắc về kích cỡ. Tôi mặc size L, nhưng áo hơi chật một chút thì có sao không?"},{"speaker":"salebot","text":"Dạ size L là vừa chuẩn ạ! Áo của chúng tôi có độ co giãn nhẹ, mặc thoải mái lắm. Bạn có muốn xem mẫu mới nhất không?"},{"speaker":"client","text":"Thế giá bao nhiêu vậy? Tôi không muốn mua đắt quá."},{"speaker":"salebot","text":"Dạ mẫu này 1.200.000đ ạ, nhưng hôm nay có khuyến mãi giảm còn 990.000đ nếu bạn đặt ngay!"},{"speaker":"client","text":"Ôi, hơi đắt so với ngân sách của tôi. Chắc tôi không mua nữa. Cảm ơn bạn nhé!"}]','fail',46),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc áo khoác gió chống nước cho mùa đông này. Bạn có thể tư vấn giúp mình không?"},{"speaker":"salebot","text":"Chào chị! Tất nhiên rồi ạ. Chị muốn mua loại áo khoác gió chống nước nào? Màu sắc hay thương hiệu ưu tiên thế nào ạ?"},{"speaker":"client","text":"Mình thích màu xanh navy, và ngân sách khoảng 1 triệu đến 1,5 triệu thôi. Có loại nào phù hợp không?"},{"speaker":"salebot","text":"Dạ, chị có thể tham khảo mẫu áo khoác gió chống nước của thương hiệu ABC ạ. Giá khoảng 1,3 triệu, có đầy đủ chứng nhận chống thấm nước. Chị có muốn xem hình ảnh chi tiết không?"},{"speaker":"client","text":"Ừ, gửi hình ảnh đi. Nhưng mình thấy trên mạng có nhiều chỗ bán rẻ hơn, có thể giảm giá không?"},{"speaker":"salebot","text":"Dạ, giá của chúng em đã là giá niêm yết ạ. Chúng em cam kết chất lượng và chế độ bảo hành 12 tháng. Nếu chị mua ngay hôm nay, mình có thể tặng chị một chiếc khăn len miễn phí ạ!"},{"speaker":"client","text":"Thế à? Nhưng mình vẫn thấy hơi đắt so với mong đợi. Thôi, cảm ơn nhé, mình suy nghĩ thêm đã."}]','fail',47),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm mua một chiếc bàn học gỗ cho phòng ngủ của mình. Có sản phẩm nào phù hợp không?"},{"speaker":"salebot","text":"Chào anh/chị ạ! Chúng tôi có rất nhiều mẫu bàn gỗ đẹp, từ cổ điển đến hiện đại. Anh/chị ưa thích kiểu dáng nào nhất?"},{"speaker":"client","text":"Tôi thích kiểu đơn giản, màu nâu gỗ tự nhiên. Giá khoảng 3-4 triệu thôi."},{"speaker":"salebot","text":"Dạ, mẫu bàn gỗ thông dụng 3 ngăn của chúng tôi có giá 3.8 triệu, đủ bền và đẹp. Anh/chị có muốn xem hình ảnh không?"},{"speaker":"client","text":"À, tôi thấy nó hơi nhỏ, bàn học cần đủ rộng. Cái khác có size lớn hơn không?"},{"speaker":"salebot","text":"Dạ, chúng tôi có mẫu bàn rộng 120cm giá 5.2 triệu, nhưng anh/chị có thể xem trước tại cửa hàng ạ. Chúng tôi có showroom ở Quận 1."},{"speaker":"client","text":"Thế à, nhưng tôi ở xa quá, không tiện đến xem. Cảm ơn bạn nhé!"}]','fail',48),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm kiếm một chiếc điện thoại có dung lượng pin lớn, tầm 5000mAh trở lên. Bạn có thể giới thiệu cho tôi một số sản phẩm phù hợp không?"},{"speaker":"salebot","text":"Chào bạn! Tôi rất vui khi hỗ trợ bạn. Hiện tại chúng tôi có dòng điện thoại Samsung Galaxy A54 với pin 5000mAh, giá chỉ 8 triệu rưỡi. Ngoài ra còn có Xiaomi Redmi Note 12 Pro+ 5G với pin 5000mAh, giá 7 triệu. Bạn thích mẫu nào hơn?"},{"speaker":"client","text":"Mình thích Samsung Galaxy A54 hơn. Màu sắc thì sao? Có màu nào?"},{"speaker":"salebot","text":"Dòng Samsung Galaxy A54 có 4 màu: Đen, Trắng, Xanh lam và Tím. Bạn thích màu nào nhất? Mình có thể tư vấn thêm về màu sắc nhé!"},{"speaker":"client","text":"Mình thích màu Tím. Có khuyến mại gì không vậy?"},{"speaker":"salebot","text":"Hiện tại chúng tôi đang có chương trình tặng kèm ốp lưng và dán màn hình miễn phí cho đơn hàng trong hôm nay. Ngoài ra còn free ship toàn quốc. Bạn có muốn đặt ngay không?"},{"speaker":"client","text":"Ok, mình chọn màu Tím. Đặt luôn nhé. Bao lâu thì nhận được hàng?"},{"speaker":"salebot","text":"Cảm ơn bạn đã mua hàng! Đơn hàng sẽ được giao trong 2-3 ngày làm việc. Bạn vui lòng cung cấp địa chỉ nhận hàng để tôi xử lý đơn hàng nhé!"}]','successs',49),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm mua một chiếc đồng hồ thể thao cho bé trai 10 tuổi. Có sản phẩm nào phù hợp không?"},{"speaker":"salebot","text":"Chào anh/chị! Rất vui được hỗ trợ. Chúng tôi có dòng đồng hồ thể thao chống nước, màu xanh dương, phù hợp cho bé trai. Giá 499.000đ, có kèm bảo hành 1 năm."},{"speaker":"client","text":"Hmm, tôi thấy hơi đắt. Có giảm giá không? Hay có chương trình khuyến mại gì không?"},{"speaker":"salebot","text":"Thời điểm này chúng tôi không có chương trình giảm giá, nhưng anh/chị có thể đăng ký nhận thông tin khuyến mại mới nhất qua email để nhận ưu đãi sau nhé!"},{"speaker":"client","text":"À vậy thì thôi. Cảm ơn bạn nhé, tôi sẽ suy nghĩ thêm."}]','fail',50),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm mua một chiếc bàn học mới cho con gái tôi. Cô ấy năm nay học lớp 5, cần bàn vừa tầm với em ấy. Bạn có mẫu nào phù hợp không?"},{"speaker":"salebot","text":"Chào chị ạ! Cảm ơn chị đã quan tâm đến sản phẩm của chúng tôi. Chị có thể tham khảo mẫu bàn học có điều chỉnh độ cao từ 60-90cm, vừa vặn cho bé lớp 5. Chị muốn màu sắc hay chất liệu nào ạ?"},{"speaker":"client","text":"Màu sắc thì em bé nhà tôi thích màu xanh dương nhạt. Còn chất liệu thì bền chắc một chút, dễ vệ sinh thôi. Bạn có thể tư vấn giá luôn không?"},{"speaker":"salebot","text":"Dạ, mẫu bàn xanh dương của chúng tôi sử dụng gỗ công nghiệp chống trầy xước, giá chỉ 1.299.000đ thôi chị. Đi kèm còn có ngăn kéo đựng đồ và giá sách nữa ạ. Chị có muốn tôi gửi link đặt hàng không?"},{"speaker":"client","text":"Ồ, giá như vậy hợp lý quá! Tôi sẽ đặt mua ngay. Có giao hàng tận nhà không? Tôi ở quận 7."},{"speaker":"salebot","text":"Dạ có ạ! Chúng tôi giao miễn phí trong nội thành TPHCM, thời gian dự kiến 2-3 ngày. Chị cung cấp địa chỉ cụ thể và số điện thoại để nhân viên liên hệ nhé?"}]','successs',51),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm kiếm một chiếc điện thoại có giá tầm 5 triệu thôi. Có gì giới thiệu không?"},{"speaker":"salebot","text":"Chào anh/chị ạ! Em có ngay một mẫu điện thoại tầm 5 triệu là Xiaomi Redmi Note 12. Màn hình AMOLED 90Hz, pin 5000mAh, cấu hình mượt mà lắm ạ!"},{"speaker":"client","text":"Ui, nghe cũng ổn đấy. Nhưng tôi không thích thương hiệu Trung Quốc lắm, có sản phẩm nào khác không?"},{"speaker":"salebot","text":"Dạ, em xin lỗi vì sự lựa chọn hạn chế ạ. Bên em cũng có mẫu Samsung Galaxy A14 tầm 5 triệu, nhưng pin có hơi yếu hơn một chút ạ."},{"speaker":"client","text":"Thế à? Tôi thấy pin yếu quá không ổn đâu. Thôi tôi đi dạo xem thế nào đã."}]','fail',52),
('[{"speaker":"client","text":"Anh ơi, em cần mua một chiếc áo sơ mi trắng cỡ M, nhưng em không biết nên chọn loại vải nào cho thoải mái nhỉ?"},{"speaker":"salebot","text":"Dạ em ơi, áo sơ mi trắng cỡ M của shop có 2 loại vải phổ biến ạ: 100% cotton thoáng mát, thấm hút mồ hôi tốt, hay cotton pha có độ co giãn nhẹ, thoải mái khi vận động. Em thích loại nào ạ?"},{"speaker":"client","text":"Em thì thích cotton pha hơn vì em hay phải di chuyển nhiều, nhưng em sợ nó dễ nhăn lắm..."},{"speaker":"salebot","text":"Dạ em yên tâm ạ! Loại cotton pha của shop đã xử lý chống nhăn, chỉ cần ủi nhẹ là phẳng ngay. Ngoài ra, em có thể chọn màu trắng tinh hoặc trắng sữa, cả 2 đều rất sang trọng ạ!"},{"speaker":"client","text":"Vậy em chọn trắng sữa đi, và em muốn mua kèm 1 chiếc thắt lưng da màu nâu nữa. Giá cả thế nào vậy anh?"},{"speaker":"salebot","text":"Dạ trời ơi, combo áo sơ mi trắng sữa + thắt lưng da nâu chỉ 499k ạ (giá gốc 750k). Hôm nay shop đang tặng kèm 1 đôi tất da cá nhân nữa, em nhận luôn không ạ? Ship tận nhà trong 3 ngày thôi!"},{"speaker":"client","text":"Tuyệt vời! Em lấy luôn combo này. Địa chỉ giao là 123 Đường Lê Lợi, Phường 10, Quận 3, TP.HCM. Cảm ơn anh nha!"}]','successs',53),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm mua một chiếc bàn học cho con gái tôi. Nó học lớp 5, nên cần bàn vừa tầm với chiều cao của bé."},{"speaker":"salebot","text":"Chào chị! Cảm ơn chị đã quan tâm đến sản phẩm của chúng tôi. Chúng tôi có bàn học điều chỉnh độ cao rất tiện lợi, phù hợp cho trẻ em từ 6-12 tuổi. Chị muốn xem mẫu nào không ạ?"},{"speaker":"client","text":"À, tôi thấy giá hơi cao so với những bàn khác ngoài kia. Có mẫu nào rẻ hơn không?"},{"speaker":"salebot","text":"Chị thông cảm ạ, sản phẩm của chúng tôi sử dụng chất liệu gỗ tự nhiên và khung thép chống gỉ, nên giá thành sẽ cao hơn một chút. Nhưng chất lượng đảm bảo, chị có thể yên tâm sử dụng lâu dài."},{"speaker":"client","text":"Thế à... À không, chắc tôi sẽ suy nghĩ thêm. Cảm ơn bạn nhé!"}]','fail',54),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm mua một chiếc bàn phím cơ cho công việc văn phòng. Bạn có thể giới thiệu sản phẩm tốt nhất không?"},{"speaker":"salebot","text":"Chào anh/chị! Tôi rất vui khi được hỗ trợ. Đối với bàn phím cơ, mình khuyên dùng sản phẩm **Keychron K8** – chất lượng tốt, bàn phím có độ nẩy tốt, phù hợp cho công việc lâu dài. Anh/chị có nhu cầu về màu sắc hay thương hiệu nào không?"},{"speaker":"client","text":"Tôi thích kiểu dáng đơn giản, màu trắng hoặc đen. Giá khoảng 2 triệu đến 3 triệu thôi."},{"speaker":"salebot","text":"Dạ, Keychron K8 phiên bản màu trắng giá chỉ 2,8 triệu thôi ạ. Đi kèm còn có tặng kèm bàn phím không dây miễn phí, giao hàng trong 2 ngày. Anh/chị có muốn đặt mua không?"},{"speaker":"client","text":"Ừ, tôi chọn màu trắng nhé. Bao lâu thì nhận được hàng?"},{"speaker":"salebot","text":"Dạ, anh/chị sẽ nhận hàng trong vòng 2 ngày làm việc. Sau khi thanh toán, mình sẽ gửi mã theo dõi đơn hàng qua Zalo ạ. Anh/chị có cần hỗ trợ thêm gì không?"},{"speaker":"client","text":"Không cần nữa, cảm ơn bạn nhé!"},{"speaker":"salebot","text":"Dạ, cảm ơn anh/chị đã mua hàng! Chúc anh/chị một ngày làm việc hiệu quả. Hẹn gặp lại!"}]','successs',55),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm kiếm một chiếc máy sấy tóc mới. Bạn có thể giới thiệu sản phẩm tốt nhất cho tôi không?"},{"speaker":"salebot","text":"Chào bạn! Tôi rất vui được giúp đỡ. Máy sấy tóc **Dyson Supersonic** là sản phẩm được ưa chuộng nhất hiện nay với công nghệ sấy siêu tốc và bảo vệ tóc tối ưu. Bạn có nhu cầu về công suất hay tính năng đặc biệt nào không?"},{"speaker":"client","text":"Tôi muốn một sản phẩm nhẹ nhàng và không quá ồn. Tôi thấy nó khá đắt, có lựa chọn nào rẻ hơn không?"},{"speaker":"salebot","text":"Nếu bạn muốn tiết kiệm hơn, tôi đề xuất **Philips HP8103/00** với giá chỉ 1.2 triệu đồng. Nó nhẹ (chỉ 400g), độ ồn thấp và có 3 chế độ nhiệt độ. Bạn thấy sao?"},{"speaker":"client","text":"Nghe ổn đấy! Tôi sẽ chọn chiếc Philips này. Bạn có thể giao hàng trong ngày không?"},{"speaker":"salebot","text":"Chắc chắn rồi! Chúng tôi có giao hàng trong ngày tại khu vực của bạn. Bạn vui lòng cung cấp địa chỉ và số điện thoại để chúng tôi xử lý đơn hàng nhé!"}]','successs',56),
('[{"speaker":"client","text":"Anh ơi, em đang tìm mua một chiếc áo sơ mi trắng cho công ty. Có size 36 không vậy?"},{"speaker":"salebot","text":"Dạ, chào chị! Chúng tôi có size 36 cho áo sơ mi trắng ạ. Chị muốn chọn kiểu dáng nào? Cổ đứng hay cổ sơ mi?"},{"speaker":"client","text":"Em thích kiểu cổ đứng, mặc thoải mái hơn. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ, giá 399.000đ chị nhé. Chị chọn màu trắng chuẩn hay có màu ngà ạ?"},{"speaker":"client","text":"Màu trắng chuẩn thôi. Ship tận nơi được không? Em ở quận 1."},{"speaker":"salebot","text":"Dạ, được chị ạ! Ship nội thành 25.000đ, giao trong 2-3 ngày làm việc. Chị có muốn thanh toán COD không?"},{"speaker":"client","text":"Ok, em chọn COD. Cảm ơn anh nhé!"},{"speaker":"salebot","text":"Dạ, không có gì ạ! Chúc chị ngày mới tốt lành. Hẹn gặp chị ạ!"}]','successs',57),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm mua một chiếc điện thoại mới. Bạn có thể giới thiệu sản phẩm tốt nhất cho tôi không?"},{"speaker":"salebot","text":"Chào bạn! Tôi rất vui khi được hỗ trợ. Bạn có nhu cầu gì đặc biệt không? Ví dụ như dung lượng pin lớn, camera chất lượng hay giá cả phải chăng?"},{"speaker":"client","text":"Tôi muốn một chiếc điện thoại có camera tốt và pin khỏe, giá dưới 10 triệu thôi."},{"speaker":"salebot","text":"Tôi đề xuất cho bạn chiếc điện thoại XZ Pro 2024 với camera 50MP, pin 5000mAh, giá chỉ 9,5 triệu. Bạn có muốn xem chi tiết không?"},{"speaker":"client","text":"Nghe ổn đấy! Tôi có thể mua online được không? Và giao hàng trong bao lâu?"},{"speaker":"salebot","text":"Hoàn toàn được nha! Bạn chỉ cần chọn phương thức thanh toán (COD hay chuyển khoản) và địa chỉ giao hàng. Đơn hàng sẽ giao trong 2-3 ngày."},{"speaker":"client","text":"Tuyệt vời! Tôi chọn thanh toán COD và địa chỉ là 123 Đường ABC, Quận 1. Cảm ơn bạn nhiều!"},{"speaker":"salebot","text":"Cảm ơn bạn đã mua hàng! Chúng tôi sẽ liên hệ xác nhận đơn hàng ngay. Chúc bạn một ngày tốt lành!"}]','successs',58),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm mua một chiếc áo sơ mi nam chất liệu cotton thoáng mát cho mùa hè này. Bạn có thể giới thiệu sản phẩm không?"},{"speaker":"salebot","text":"Dạ chào anh! Chúng tôi có sẵn dòng áo sơ mi cotton 100% từ thương hiệu XYZ, giá 399.000đ, thoáng mát và chống nhăn rất tốt ạ."},{"speaker":"client","text":"À, vậy có màu gì nhỉ? Tôi thích màu xanh dương nhưng không biết size L có vừa không."},{"speaker":"salebot","text":"Dạ màu xanh dương thì hôm nay hết size L rồi ạ, chỉ còn size M và XL thôi. Anh có thể thử size M xem sao, thường size M của chúng tôi khá rộng rãi."},{"speaker":"client","text":"Tôi mặc thường size L mà, size M chắc không vừa đâu. Thôi tôi để dành dịp khác vậy nhé. Cảm ơn bạn!"}]','fail',59),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm kiếm một chiếc áo khoác mùa đông cho bé trai 8 tuổi. Giá khoảng dưới 1 triệu thôi nhé."},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Em có ngay những mẫu áo khoác ấm áp, chống gió cho bé trai 8 tuổi trong tầm giá 800k-1.2 triệu. Anh/chị thích kiểu dáng nào nhất: cổ bẻ, cổ tròn hay có mũ?"},{"speaker":"client","text":"Tôi thích kiểu cổ bẻ, màu xanh dương hoặc xám. Có size cho bé nặng 30kg không?"},{"speaker":"salebot","text":"Dạ có ạ! Size L phù hợp cho bé 30kg. Em gửi link sản phẩm này cho anh/chị nhé: [link]. Màu xanh dương còn 2 chiếc, xám thì 5 chiếc. Anh/chị muốn đặt ngay không ạ?"},{"speaker":"client","text":"Tôi chọn màu xanh dương. Giao hàng trong 2 ngày được không? Tôi ở quận 1."},{"speaker":"salebot","text":"Dạ được ạ! Em sẽ xử lý đơn hàng ngay. Tổng cộng 950k (giá sản phẩm 890k + phí ship 60k). Anh/chị thanh toán bằng tiền mặt hay chuyển khoản? Em gửi thông tin tài khoản ngay đây!"},{"speaker":"client","text":"Tôi chuyển khoản nhé. Cảm ơn bạn nhiều!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Chúc anh/chị ngày mới vui vẻ. Đơn hàng sẽ giao vào 14h-16h ngày mai ạ. Em sẵn sàng hỗ trợ nếu có thắc mắc!"}]','successs',60),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm mua một chiếc laptop cho con trai mình. Nó học đại học nên cần cấu hình mạnh nhưng giá cũng phải hợp lý."},{"speaker":"salebot","text":"Chào anh/chị ạ! Em là trợ lý của cửa hàng. Anh/chị có nhu cầu về dung lượng RAM, bộ nhớ hay thương hiệu nào không ạ?"},{"speaker":"client","text":"RAM tối thiểu 8GB, ổ cứng 512GB SSD trở lên. Thương hiệu Dell hoặc ASUS thì tốt."},{"speaker":"salebot","text":"Dell Inspiron 15 3000 hoặc ASUS Vivobook Pro 14 vừa đủ tiêu chuẩn ạ! Đang có chương trình khuyến mại 15% cho sinh viên. Anh/chị có muốn xem ảnh và thông số chi tiết không?"},{"speaker":"client","text":"Ừ, gửi link cho tôi. Tôi muốn so sánh giá với vài cửa hàng khác."},{"speaker":"salebot","text":"Dạ, đây ạ: [link sản phẩm]. Ngoài ra, nếu anh/chị mua trong hôm nay, em có thể hỗ trợ giao hàng tận nơi miễn phí trong nội thành. Anh/chị quyết định chưa ạ?"},{"speaker":"client","text":"Tôi thấy ổn, đặt luôn 1 chiếc Dell Inspiron đi. Tôi cung cấp địa chỉ: 123 Lê Lợi, Quận 1, TP.HCM."},{"speaker":"salebot","text":"Cảm ơn anh/chị! Đơn hàng #20240515 đã được ghi nhận. Chúng tôi sẽ giao trong vòng 24 giờ. Anh/chị có muốn nhận thông báo qua email/SMS không ạ?"}]','successs',61),
('[{"speaker":"client","text":"Chào bạn, tôi thấy shop có bán bàn ghế gỗ tự nhiên. Cho tôi hỏi giá của bộ bàn ghế phòng khách loại 5 ghế này là bao nhiêu vậy?"},{"speaker":"salebot","text":"Chào bạn ạ! Bộ bàn ghế phòng khách 5 ghế của chúng tôi hiện đang có giá 12.500.000đ, ạ. Bạn muốn mua luôn hay xem thêm mẫu khác trước ạ?"},{"speaker":"client","text":"12 triệu rưỡi à? Đắt quá! Tôi thấy trên mạng có nhiều chỗ bán rẻ hơn mà. Thôi để tôi suy nghĩ đã."},{"speaker":"salebot","text":"Dạ vâng ạ! Nếu bạn cần tư vấn thêm hoặc muốn so sánh giá thì cứ nhắn tin cho shop nhé. Chúc bạn một ngày tốt lành!"}]','fail',62),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc áo sơ mi nam chất lượng nhưng giá cả phải chăng. Bạn có thể giới thiệu sản phẩm không?"},{"speaker":"salebot","text":"Chào bạn! Tất nhiên rồi. Hiện chúng tôi có dòng áo sơ mi nam từ vải cotton thoáng mát, giá chỉ 399.000đ. Bạn muốn xem mẫu nào không?"},{"speaker":"client","text":"399k hơi đắt so với mình. Có loại nào rẻ hơn không? Mình chỉ cần mặc đi làm thôi."},{"speaker":"salebot","text":"Dạ, chúng tôi cũng có dòng áo giá 249.000đ nhưng vải polyester nhé. Hoặc nếu bạn mua 2 cái sẽ được giảm 10% đó!"},{"speaker":"client","text":"Thế à... nhưng mình không cần mua 2 cái. Cảm ơn bạn nhiều nhé!"}]','fail',63),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc áo khoác gió cho mùa đông sắp tới. Có gì giới thiệu không?"},{"speaker":"salebot","text":"Chào chị ạ! Chúng tôi có nhiều mẫu áo khoác gió chống gió và chống thấm tuyệt vời. Chị thích màu sắc hay kiểu dáng nào nhất?"},{"speaker":"client","text":"Mình thích màu xanh navy, nhưng giá cả có phải chăng không? Mình sinh viên nên ngân sách có hạn."},{"speaker":"salebot","text":"Dạ, mẫu áo khoác gió chống gió chống thấm này giá 499.000đ, chị có thể thanh toán trả góp 0% nếu chị muốn ạ!"},{"speaker":"client","text":"Trả góp 0% thì mình phải đăng ký thế nào? Mà mình thấy hơi đắt so với những nơi khác."},{"speaker":"salebot","text":"Dạ, chị chỉ cần đăng ký tài khoản, chọn phương thức trả góp là được ạ. Còn về giá, chúng tôi cam kết chất lượng vải chống gió chống thấm chuẩn Nhật Bản, chị có thể so sánh với sản phẩm tương đương trên thị trường nhé."},{"speaker":"client","text":"Thế à... nhưng mình không chắc lắm. Mình nghĩ sẽ tìm hiểu thêm rồi quay lại sau vậy. Cảm ơn bạn nhé!"}]','fail',64),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm mua một chiếc điện thoại thông minh mới. Bạn có thể tư vấn giúp tôi không?"},{"speaker":"salebot","text":"Chào chị! Em rất vui được hỗ trợ chị. Chị muốn tìm mẫu điện thoại nào? Có nhu cầu về camera, dung lượng pin hay hiệu năng không?"},{"speaker":"client","text":"Tôi muốn một chiếc có camera tốt, dung lượng pin trên 4000mAh, và giá tầm dưới 10 triệu."},{"speaker":"salebot","text":"Dạ, em có mẫu Xiaomi Redmi Note 12 Pro vừa ra mắt, camera 200MP, pin 5000mAh, giá chỉ 9,99 triệu. Chị có muốn em gửi link chi tiết không?"},{"speaker":"client","text":"Ừ, gửi link cho tôi nhé. Nếu ưng tôi sẽ mua ngay."},{"speaker":"salebot","text":"Dạ, link sản phẩm chị vừa nhận nhé! Em cũng gửi kèm mã giảm 50k cho chị nếu đặt trong hôm nay. Chị có cần hỗ trợ thêm gì không?"}]','successs',65),
('[{"speaker":"client","text":"Chào bạn! Mình đang tìm kiếm một chiếc điện thoại mới, nhưng không biết nên chọn loại nào. Bạn có thể tư vấn giúp mình không?"},{"speaker":"salebot","text":"Chào bạn! Rất vui khi được hỗ trợ. Bạn muốn mua điện thoại cho mục đích gì ạ? Chụp ảnh, chơi game hay chỉ dùng cơ bản thôi?"},{"speaker":"client","text":"Mình dùng chủ yếu để lướt web, mạng xã hội và chụp ảnh đôi khi. Ngân sách của mình khoảng 7-8 triệu thôi."},{"speaker":"salebot","text":"Vậy mình đề xuất chiếc điện thoại Samsung Galaxy A14 5G giá 7.990.000đ ạ. Máy có camera 50MP, màn hình 90Hz, ổn định cho nhu cầu của bạn. Bạn có muốn xem thêm chi tiết không?"},{"speaker":"client","text":"Nghe ổn đấy! Có giảm giá gì không? Mình thấy trên mạng thấy khuyến mại 10% nhưng không biết có đúng không."},{"speaker":"salebot","text":"Dạ, hiện tại shop đang có chương trình tặng ốp lưng cao cấp + giảm 5% cho đơn hàng đầu tiên ạ. Nếu bạn đặt ngay hôm nay, mình sẽ hỗ trợ ship miễn phí trong nội thành!"},{"speaker":"client","text":"Tuyệt quá! Vậy mình chọn màu đen nhé. Bạn giúp mình đặt hàng luôn nhé."},{"speaker":"salebot","text":"Dạ, rất cảm ơn bạn! Mình sẽ tiến hành đặt hàng ngay. Bạn vui lòng cung cấp địa chỉ nhận hàng và số điện thoại để mình xác nhận đơn hàng ạ."}]','successs',66),
('[{"speaker":"client","text":"Chào bạn! Tôi đang tìm kiếm một chiếc bàn làm việc gỗ chắc chắn cho phòng khách. Có sản phẩm nào phù hợp không?"},{"speaker":"salebot","text":"Chào chị! Cảm ơn chị đã quan tâm. Chúng tôi có bàn làm việc bằng gỗ óc chó nguyên khối, rất chắc chắn và thiết kế hiện đại. Chị muốn kích thước bao nhiêu ạ?"},{"speaker":"client","text":"Tôi cần khoảng 120x60 cm thôi. Giá bao nhiêu vậy? Có ưu đãi gì không?"},{"speaker":"salebot","text":"Dạ, bàn này giá 5 triệu 500, chị ạ. Hiện tại shop đang có chương trình giảm 10% cho đơn hàng đầu tiên trong hôm nay. Nếu chị đặt luôn chị sẽ được free giao hàng tận nơi nữa!"},{"speaker":"client","text":"Ồ, vậy thì tốt quá! Tôi chọn màu nâu đậm nhé. Bao lâu thì giao được?"},{"speaker":"salebot","text":"Dạ, chị yên tâm ạ! Chúng tôi sẽ giao trong vòng 3 ngày làm việc. Chị để lại số điện thoại và địa chỉ chi tiết để shop xác nhận đơn hàng nhé!"}]','successs',67),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm mua một chiếc bàn học gỗ cho con gái tôi. Nó học lớp 5, nên cần kiểu dáng đơn giản nhưng chắc chắn thôi."},{"speaker":"salebot","text":"Chào chị! Cảm ơn chị đã quan tâm sản phẩm của chúng tôi. Chị muốn bàn gỗ có kích thước bao nhiêu ạ? Màu sắc ưa thích là gì?"},{"speaker":"client","text":"Kích thước vừa phải thôi, khoảng 120x60 cm là được. Màu nâu nhạt hoặc trắng sữa thì đẹp."},{"speaker":"salebot","text":"Dạ, chị có thể tham khảo mẫu BÀN HỌC GỖ TỰ NHIÊN LOẠI A nhé! Giá 1.890.000đ, giao tận nhà trong 3 ngày. Chị có muốn đặt không?"},{"speaker":"client","text":"Ôi, giá hơi cao so với dự định của tôi. Tôi thấy trên mạng có bàn tương tự chỉ 1.2 triệu thôi..."},{"speaker":"salebot","text":"Dạ, sản phẩm của chúng tôi sử dụng gỗ tự nhiên nguyên khối, đảm bảo độ bền 10 năm chị nhé. Chị có thể trả góp 0% không lãi suất nếu muốn ạ!"},{"speaker":"client","text":"Thế à... Nhưng tôi vẫn thấy hơi đắt. Cảm ơn bạn nhé, tôi sẽ suy nghĩ thêm."}]','fail',68),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc áo thể thao cho con trai mình. Con trai mình 12 tuổi, hay chơi bóng đá. Bạn có thể giới thiệu sản phẩm phù hợp không?"},{"speaker":"salebot","text":"Chào anh/chị ạ! Em xin giới thiệu với anh/chị mẫu áo thể thao chống thấm mồ hôi, thoáng khí, rất phù hợp cho các bé hay vận động ạ. Giá khoảng 350.000đ, anh/chị có muốn xem ảnh mẫu không?"},{"speaker":"client","text":"À, mình thấy hơi đắt so với mức giá mình định. Mình chỉ muốn mua tầm 200.000đ thôi. Bạn có sản phẩm nào rẻ hơn không?"},{"speaker":"salebot","text":"Dạ, em xin lỗi ạ. Mẫu rẻ nhất của em cũng tầm 280.000đ thôi ạ. Nhưng em đảm bảo chất lượng lắm ạ, anh/chị có thể yên tâm sử dụng ạ."},{"speaker":"client","text":"Thế à... Mình thấy trên mạng có nhiều mẫu rẻ hơn nhiều. Cảm ơn bạn nhé, mình sẽ tìm nơi khác mua."}]','fail',69),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm mua một chiếc áo khoác mùa đông cho bé nhà tôi. Giá khoảng 500k thôi nhé."},{"speaker":"salebot","text":"Chào chị ạ! Chúng tôi có nhiều loại áo khoác ấm cho bé lắm ạ. Loại cotton dày 500k chị có thể tham khảo mẫu này ạ!"},{"speaker":"client","text":"Mẫu này trông hơi dày, bé tôi hay đổ mồ hôi lắm. Có loại mỏng nhẹ hơn không?"},{"speaker":"salebot","text":"Dạ, mẫu mỏng nhẹ của chúng em tầm 700k chị nhé. Hoặc chị có thể chọn loại cotton thoáng khí 600k cũng được ạ!"},{"speaker":"client","text":"Ôi, vậy là vượt quá ngân sách rồi. Thôi tôi đi xem nơi khác vậy."}]','fail',70),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc điện thoại mới. Bạn có thể tư vấn giúp mình không?"},{"speaker":"salebot","text":"Chào bạn nhé! Mình rất vui khi hỗ trợ bạn. Bạn đang quan tâm đến dòng điện thoại nào? Ví dụ như chip mạnh, camera tốt hay pin trâu?"},{"speaker":"client","text":"Mình muốn một chiếc có camera tốt, pin trên 5000mAh và giá tầm 10-12 triệu thôi."},{"speaker":"salebot","text":"Hay quá! Bên mình đang có deal siêu hấp dẫn: **Xiaomi Redmi Note 12 Pro 5G** - camera 200MP, pin 5000mAh, giá chỉ 11.990.000đ. Bạn có muốn xem chi tiết không?"},{"speaker":"client","text":"Ồ, nghe cũng ổn đấy. Mình có thể trả góp không? Và giao hàng trong bao lâu?"},{"speaker":"salebot","text":"Dạ có nhé! Bạn có thể trả góp 0% trong 6 tháng. Giao hàng miễn phí trong 2-3 ngày ở nội thành. Bạn muốn đặt luôn không?"},{"speaker":"client","text":"Ok, mình đặt chiếc này đi. Bao lâu nhận được hàng vậy?"},{"speaker":"salebot","text":"Siêu nhanh thôi! Bạn check mail để nhận thông tin đơn hàng nhé. Cảm ơn bạn đã ủng hộ shop!"}]','successs',71),
('[{"speaker":"client","text":"Tôi đang tìm mua một chiếc áo khoác mùa đông cho bé gái 5 tuổi. Giá khoảng 300k-500k thôi nhé."},{"speaker":"salebot","text":"Chào chị ạ! Chúng tôi vừa nhập về mẫu áo khoác cute cho bé gái 5 tuổi, giá 450k thôi ạ. Chất liệu cotton mềm mại, chống lạnh tốt lắm ạ!"},{"speaker":"client","text":"Màu sắc có những màu nào vậy? Tôi thích màu hồng hoặc xanh dương."},{"speaker":"salebot","text":"Dạ, hiện tại chỉ còn màu hồng thôi ạ. Size 5-6 tuổi có sẵn ạ. Chị có muốn đặt không ạ?"},{"speaker":"client","text":"Hmm, tôi cân nhắc chút. Màu hồng thì hơi sặc sỡ quá. Có màu xanh dương không?"},{"speaker":"salebot","text":"Dạ, tiếc quá ạ! Hiện tại hết hàng màu xanh rồi ạ. Chị có thể để lại số điện thoại, khi nào nhập hàng chúng tôi sẽ báo ngay ạ!"},{"speaker":"client","text":"Thôi vậy, tôi đợi lần sau vậy. Cảm ơn nhé!"}]','fail',72),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc điện thoại thông minh tầm 5-7 triệu thôi. Có sản phẩm nào recommend không?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Em giới thiệu chị chiếc OPPO Reno8 5G giá 6,99 triệu, cấu hình khỏe, camera chụp đêm siêu đẹp, chị có thể xem thử video giới thiệu ở đây: [link]"},{"speaker":"client","text":"Ồ nhìn nóng quá! Mình thích màu xanh dương đó. Nhưng mình nghe nói OPPO hay nóng máy lắm, có thật không?"},{"speaker":"salebot","text":"Dạ không ạ, chip Snapdragon 7 Gen 1 siêu tiết kiệm pin, chị yên tâm nhé! Đặc biệt hôm nay sale ưu đãi giảm 500k, chị đặt luôn đi ạ!"},{"speaker":"client","text":"Thế giao hàng bao lâu vậy? Mình cần gấp lắm!"},{"speaker":"salebot","text":"Dạ giao trong 2h nếu chị ở nội thành HN ạ, miễn phí ship cho đơn trên 5 triệu. Chị cứ ấn ''Đặt hàng'' đi nhé!"}]','successs',73),
('[{"speaker":"client","text":"Chào bạn! Tôi đang tìm một chiếc bàn học gỗ cho con gái tôi, nó 10 tuổi. Có cái nào phù hợp không?"},{"speaker":"salebot","text":"Chào chị! Rất vui được hỗ trợ. Chị muốn bàn gỗ loại nào ạ? Gỗ tự nhiên hay gỗ công nghiệp? Màu sắc ưa thích của bé là gì?"},{"speaker":"client","text":"Gỗ tự nhiên thì tốt hơn, nhưng giá hơi cao. Gỗ công nghiệp cũng được, miễn là chắc chắn. Màu hồng nhạt hoặc xanh pastel thì đẹp."},{"speaker":"salebot","text":"Chị yên tâm nhé! Tôi có bàn gỗ công nghiệp chống ẩm, mặt bàn màu hồng pastel, giá chỉ 1.299.000đ. Đi kèm kệ sách nhỏ, rất phù hợp cho bé gái."},{"speaker":"client","text":"Nghe ổn đấy! Ship tận nhà không? Có bảo hành không?"},{"speaker":"salebot","text":"Dạ có ạ! Ship miễn phí trong 24h, bảo hành 1 năm. Chị có thể thanh toán online hay COD đều được. Chị muốn đặt ngay không?"},{"speaker":"client","text":"Ok, tôi chọn màu hồng. Đặt luôn nhé! Cảm ơn bạn nhiều."},{"speaker":"salebot","text":"Dạ không có gì ạ! Đơn hàng của chị đã được ghi nhận. Chúc chị một ngày tốt lành!"}]','successs',74),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc áo thể thao cho bé nhà mình. Bé trai 8 tuổi, hay chạy nhảy nên ưu tiên thoáng mát. Bạn có gợi ý gì không?"},{"speaker":"salebot","text":"Chào chị! Em rất vui khi được hỗ trợ. Chị có thể tham khảo mẫu áo thể thao chống thấm mồ hôi của thương hiệu XYZ ạ. Sản phẩm có chất liệu thoáng khí, co giãn tốt, phù hợp cho các bé năng động như vậy."},{"speaker":"client","text":"Nghe ổn đấy. Giá bao nhiêu vậy? Mình muốn mua tặng sinh nhật bé vào tuần sau."},{"speaker":"salebot","text":"Hiện sản phẩm đang khuyến mại 30% chị nhé! Giá gốc 500k, nay chỉ còn 350k thôi. Đi kèm còn tặng bé 1 chiếc khăn thể thao xinh xắn nữa ạ."},{"speaker":"client","text":"Tuyệt quá! Mình chọn size L nhé, bé nhà mình hơi cao so với tuổi. Bao lâu thì giao được?"},{"speaker":"salebot","text":"Size L vẫn còn hàng chị nhé! Em sẽ đặt hàng ngay và giao trong 2-3 ngày làm việc. Chị có thể chọn nhận hàng tận nơi hoặc đến lấy tại cửa hàng ạ."},{"speaker":"client","text":"Nhận tận nơi nhé. Địa chỉ là 123 Đường Lê Lợi, Phường 1, Quận 1, TP. HCM. Cảm ơn bạn nhiều!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Em đã ghi nhận đơn hàng. Chúc chị và bé trai có sinh nhật thật vui vẻ! Hẹn gặp lại chị nhé."}]','successs',75),
('[{"speaker":"client","text":"Chào bạn! Tôi đang tìm một chiếc bàn làm việc gỗ cho phòng khách, nhưng không biết nên chọn loại nào. Bạn có thể tư vấn giúp tôi không?"},{"speaker":"salebot","text":"Dạ chào chị! Chị có thể tham khảo dòng bàn gỗ sồi tự nhiên của chúng em ạ. Chất liệu bền, thiết kế hiện đại, phù hợp với không gian phòng khách. Chị muốn kích thước nào ạ?"},{"speaker":"client","text":"Tôi thấy kích thước 120x60cm là vừa phải. Màu sắc thì nên chọn màu gì cho phù hợp với nội thất nhà tôi?"},{"speaker":"salebot","text":"Dạ chị có thể chọn màu nâu nhạt hoặc màu gỗ tự nhiên ạ. Cả hai màu đều sang trọng và dễ kết hợp. Ngoài ra, nếu chị muốn, chúng em có dịch vụ miễn phí giao hàng lắp đặt tận nơi ạ!"},{"speaker":"client","text":"Thế giá cả thế nào? Tôi muốn biết cả phí vận chuyển nữa nhé."},{"speaker":"salebot","text":"Dạ sản phẩm có giá 2.500.000đ, phí vận chuyển trong nội thành là 50.000đ ạ. Nếu chị đặt trong hôm nay, chúng em sẽ tặng quà là bộ bàn ghế phụ kiện đi kèm ạ!"},{"speaker":"client","text":"Hay quá! Tôi quyết định mua ngay. Làm thế nào để thanh toán?"},{"speaker":"salebot","text":"Dạ chị vui lòng chuyển khoản vào số tài khoản 123456789 (Ngân hàng X) hoặc chọn thanh toán khi nhận hàng ạ. Sau khi nhận được tiền, chúng em sẽ giao hàng trong vòng 24 giờ ạ!"}]','successs',76),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc túi xách da thật cho dịp lễ sắp tới. Bạn có thể giới thiệu sản phẩm nào phù hợp không?"},{"speaker":"salebot","text":"Chào chị! Mình rất vui khi chị quan tâm đến sản phẩm túi xách da của shop. Hiện tại, chúng mình đang có mẫu túi da lộn màu nâu đen rất hot, vừa sang trọng lại bền đẹp. Chị có thích xem ảnh sản phẩm không?"},{"speaker":"client","text":"Ừ, gửi mình ảnh sản phẩm đi. Mình thích kiểu dáng đơn giản nhưng chất liệu tốt. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ, túi này có giá 1.299.000₫, chất liệu da lộn nhập khẩu từ Ý ạ. Mình gửi ảnh sản phẩm cho chị ngay đây! (ảnh) Chị thấy có ưng không ạ?"},{"speaker":"client","text":"Đẹp quá! Mình quyết định mua rồi. Bạn có thể giao hàng tận nơi không? Địa chỉ mình là 123 Lê Lợi, quận 1, TP. HCM."},{"speaker":"salebot","text":"Dạ, shop giao hàng toàn quốc ạ. Chị có thể chọn giao trong ngày hoặc ngày mai đều được. Mình sẽ gửi đơn hàng ngay bây giờ. Chúc chị có một trải nghiệm mua sắm vui vẻ!"}]','successs',77),
('[{"speaker":"client","text":"Chào bạn! Mình đang tìm mua một chiếc điện thoại mới, nhưng không biết nên chọn loại nào. Bạn có thể tư vấn giúp mình không?"},{"speaker":"salebot","text":"Chào bạn! Tất nhiên rồi. Bạn đang có nhu cầu gì ưu tiên nhất trên chiếc điện thoại sắp mua vậy? Ví dụ như dung lượng pin, camera hay hiệu năng?"},{"speaker":"client","text":"Mình thích chụp ảnh nên camera phải tốt thôi. Mình cũng muốn dung lượng pin lớn vì hay đi chơi xa."},{"speaker":"salebot","text":"Vậy mình gợi ý bạn chiếc iPhone 15 Pro Max nhé! Camera 48MP siêu nét, pin 4400mAh dùng cả ngày không lo hết pin. Giá hiện tại 28 triệu, bạn có nhu cầu mua không?"},{"speaker":"client","text":"Ồ, nghe cũng ổn. Nhưng mình nghe nói iPhone có giá đắt hơn các hãng khác. Bạn có chương trình khuyến mãi gì không?"},{"speaker":"salebot","text":"Chúng tôi đang có chương trình tặng kèm tai nghe AirPods Gen 3 trị giá 4 triệu khi mua iPhone 15 Pro Max. Ngoài ra, bạn có thể trả góp 0% trong 12 tháng nữa đó!"},{"speaker":"client","text":"Hay quá! Vậy mình quyết định mua luôn. Bạn giúp mình đặt hàng với nhé."},{"speaker":"salebot","text":"Cảm ơn bạn đã tin tưởng! Mình sẽ tiến hành đặt hàng ngay. Bạn vui lòng cung cấp địa chỉ nhận hàng và số điện thoại để chúng tôi liên hệ nhé."}]','successs',78),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm mua một chiếc laptop cho con gái tôi. Nó học ngành thiết kế đồ họa, nên cần cấu hình mạnh nhưng cũng không quá đắt."},{"speaker":"salebot","text":"Chào chị! Tôi rất vui khi được tư vấn cho chị. Để con gái chị học thiết kế đồ họa, mình nên chọn laptop có CPU Intel Core i5/i7 và card đồ họa rời nhé. Chị có mức giá mong muốn không?"},{"speaker":"client","text":"Tầm 15-20 triệu thôi. Nó mới vào đại học nên mình không muốn đầu tư quá nhiều."},{"speaker":"salebot","text":"À chị ơi, với mức giá đó thì khó có laptop có card đồ họa rời ổn định lắm. Chị có thể cân nhắc dùng card onboard tạm thời, hoặc tăng ngân sách lên 25-30 triệu để có sản phẩm tốt hơn không?"},{"speaker":"client","text":"Thế à... vậy thì thôi. Chị sẽ để dành thêm tiền rồi quay lại sau. Cảm ơn bạn nhé!"}]','fail',79),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm mua một chiếc bàn phím cơ cho công việc văn phòng. Bạn có thể giới thiệu cho tôi một sản phẩm tốt không?"},{"speaker":"salebot","text":"Chào chị ạ! Em rất vui khi được hỗ trợ chị. Em thấy bàn phím cơ Keychron K8 mới ra mắt có độ nảy tốt, phù hợp cho văn phòng. Chị có thích màu sắc nào không ạ?"},{"speaker":"client","text":"Tôi thích màu xám bạc. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ, bàn phím Keychron K8 màu xám bạc có giá 2.490.000đ, chị ạ. Hiện có giảm giá 10% nếu chị đặt trong hôm nay nữa."},{"speaker":"client","text":"Tuyệt quá! Tôi sẽ mua ngay. Bạn gửi link đặt hàng cho tôi nhé."},{"speaker":"salebot","text":"Dạ vâng chị! Em gửi link đặt hàng qua tin nhắn ngay đây. Cảm ơn chị đã ủng hộ ạ!"}]','successs',80),
('[{"speaker":"client","text":"Tôi đang tìm mua một chiếc áo khoác mùa đông cho bé gái 5 tuổi, nhưng không biết chọn loại nào cho ấm mà vẫn thoải mái."},{"speaker":"salebot","text":"Chào chị! Tôi có thể gợi ý cho chị mẫu áo khoác lông cừu siêu nhẹ, chống gió và thoáng khí nhé. Loại này được các mẹ đánh giá rất tốt về độ ấm và an toàn cho trẻ nhỏ."},{"speaker":"client","text":"À, nhưng tôi lo là bé nhà tôi hay bị dị ứng da, không biết chất liệu có an toàn không?"},{"speaker":"salebot","text":"Không sao đâu chị! Chất liệu 100% cotton organic, không hóa chất gây kích ứng. Ngoài ra, sản phẩm còn có chứng nhận an toàn từ viện kiểm nghiệm quốc tế."},{"speaker":"client","text":"Vậy giá bao nhiêu vậy? Tôi thấy hơi đắt so với túi tiền của mình..."},{"speaker":"salebot","text":"Chị thông cảm nhé, chất lượng đi đôi với giá cả. Nhưng nếu chị mua ngay hôm nay, tôi có thể giảm 10% cho chị và tặng kèm một chiếc khăn len nhỏ."},{"speaker":"client","text":"Thế thì cũng được, nhưng tôi cần xem trước sản phẩm trực tiếp mới quyết định. Bao giờ shop giao hàng tận nhà được?"},{"speaker":"salebot","text":"Rất tiếc chị ơi, shop chỉ giao hàng tận nơi ở khu vực nội thành Hà Nội, TP. Hồ Chí Minh và Đà Nẵng thôi. Còn chị ở tỉnh khác thì phải tự đến lấy hoặc sử dụng dịch vụ vận chuyển bên thứ ba."},{"speaker":"client","text":"Ôi, vậy thì phiền quá. Tôi nghĩ tôi sẽ cân nhắc lại. Cảm ơn chị nhé!"}]','fail',81),
('[{"speaker":"client","text":"Tôi đang tìm một chiếc áo sơ mi nam chất liệu cotton thoáng mát cho mùa hè này. Bạn có thể giới thiệu sản phẩm không?"},{"speaker":"salebot","text":"Dạ vâng! Chúng tôi có bộ sưu tập áo sơ mi nam 100% cotton từ thương hiệu ABC, thoáng khí và chống nhăn. Bạn muốn màu nào ạ?"},{"speaker":"client","text":"Màu xanh dương nhạt hoặc trắng thì được không? Tôi thích những màu nhẹ nhàng."},{"speaker":"salebot","text":"Dạ vâng! Chúng tôi có cả hai màu ạ. Size của bạn là gì ạ? Để tôi kiểm tra kho cho bạn."},{"speaker":"client","text":"Tôi mặc size M thôi. Nhưng giá bao nhiêu vậy? Tôi thấy hơi đắt so với những nơi khác."},{"speaker":"salebot","text":"Dạ sản phẩm của chúng tôi sử dụng chất liệu cotton nhập khẩu từ Ai Cập, nên giá thành hơi cao hơn một chút ạ. Nhưng chất lượng đảm bảo ạ!"},{"speaker":"client","text":"Tôi hiểu rồi, nhưng tôi vẫn thấy hơi đắt. Thôi tôi nghĩ sẽ tìm nơi khác mua vậy."}]','fail',82),
('[{"speaker":"client","text":"Chào bạn, tôi thấy shop có bán áo sơ mi nữ giá 300k. Có size S không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Size S vẫn còn hàng, chị muốn mua thì shop sẽ gửi nhanh nhất có thể nha."},{"speaker":"client","text":"À, nhưng tôi thấy màu hơi tối, có màu sáng hơn không? Màu pastel ấy."},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, size S hiện tại chỉ còn màu xanh navy và trắng. Màu pastel shop hết hàng rồi ạ."},{"speaker":"client","text":"Thế à... Vậy thôi, tôi không mua nữa. Cảm ơn nhé!"}]','fail',83),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm mua một chiếc áo khoác mùa đông cho bé gái 5 tuổi. Bạn có thể giới thiệu cho tôi không?"},{"speaker":"salebot","text":"Chào chị! Tất nhiên rồi ạ. Chúng tôi có loại áo khoác cotton dày, chống gió, màu hồng rất dễ thương cho bé. Giá chỉ 350.000đ thôi chị nhé!"},{"speaker":"client","text":"Màu hồng thì có size nào? Tôi muốn size 6 tuổi."},{"speaker":"salebot","text":"Size 6 tuổi ạ, còn 3 chiếc thôi chị ơi. Chị muốn đặt trước không? Có ưu đãi giảm 10% nếu đặt ngay hôm nay!"},{"speaker":"client","text":"Ok, tôi chọn màu hồng size 6 tuổi. Bao giờ giao được?"},{"speaker":"salebot","text":"Chị đặt xong trong 5 phút nữa là giao được luôn ạ! Địa chỉ giao hàng là nhà chị chứ ạ?"}]','successs',84),
('[{"speaker":"client","text":"Chào bạn, tôi thấy shop bán điện thoại iPhone 15 Pro Max giá 32 triệu, có giảm giá không vậy?"},{"speaker":"salebot","text":"Chào bạn ạ! Hiện tại iPhone 15 Pro Max đang có chương trình khuyến mại 5% cho đơn hàng từ 2 sản phẩm trở lên ạ."},{"speaker":"client","text":"Tôi chỉ mua 1 cái thôi, vậy không được giảm à?"},{"speaker":"salebot","text":"Dạ thôi ạ, nhưng nếu bạn mua thêm phụ kiện như ốp lưng hay sạc dự phòng thì có thể được giảm 2% nữa ạ."},{"speaker":"client","text":"Không cần đâu, tôi chỉ cần điện thoại thôi. Thôi vậy tôi không mua nữa, cảm ơn nhé!"}]','fail',85),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc điện thoại mới. Bạn có thể giới thiệu cho mình một sản phẩm tốt không?"},{"speaker":"salebot","text":"Dạ chào chị! Em thấy chị phù hợp với chiếc iPhone 15 128GB thì sao ạ? Mẫu mới nhất, camera siêu đẹp, pin trâu lắm!"},{"speaker":"client","text":"Ui, mình không thích iPhone. Mình dùng Android thôi. Bạn có sản phẩm nào khác không?"},{"speaker":"salebot","text":"Dạ em xin lỗi chị ạ! Vậy chị thử xem qua chiếc Samsung Galaxy S23 Ultra xem thế nào? Mẫu này cũng rất ổn, chụp ảnh siêu nét luôn!"},{"speaker":"client","text":"Mình không thích Samsung nữa. Bạn có sản phẩm nào khác không? Mình đang bận nên muốn mua nhanh thôi."},{"speaker":"salebot","text":"Dạ em xin lỗi chị vì không đáp ứng được nhu cầu ạ. Chúc chị một ngày vui vẻ ạ!"}]','fail',86),
('[{"speaker":"client","text":"Chào bạn! Tôi đang tìm kiếm một chiếc bàn làm việc gỗ chắc chắn cho phòng khách. Bạn có thể giới thiệu sản phẩm phù hợp không?"},{"speaker":"salebot","text":"Chào anh/chị! Tôi rất vui khi được hỗ trợ. Chúng tôi có bàn làm việc bằng gỗ óc chó nguyên khối, rất chắc chắn và thẩm mỹ. Bạn có thích màu nâu tự nhiên hay màu sơn bóng?"},{"speaker":"client","text":"Tôi thích màu nâu tự nhiên, nhưng kích thước phải vừa phòng khách nhà tôi thôi. Bao nhiêu tiền vậy?"},{"speaker":"salebot","text":"Sản phẩm màu nâu tự nhiên có giá 2.990.000đ, kích thước 120x60cm. Đi kèm 2 ngăn kéo tiện dụng. Anh/chị có muốn đặt ngay không ạ?"},{"speaker":"client","text":"Được thôi, tôi chọn sản phẩm này. Bao giờ giao được?"},{"speaker":"salebot","text":"Cảm ơn anh/chị đã đặt hàng! Sản phẩm sẽ được giao trong vòng 3-5 ngày làm việc. Tôi sẽ gửi mã vận đơn qua email sau khi thanh toán thành công. Anh/chị có cần hỗ trợ gì thêm không?"}]','successs',87),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc điện thoại mới. Bạn có thể tư vấn giúp mình không?"},{"speaker":"salebot","text":"Chào bạn! Mình rất vui được tư vấn. Bạn đang quan tâm đến dòng điện thoại nào, dung lượng bao nhiêu, hay ngân sách của bạn là bao nhiêu?"},{"speaker":"client","text":"Mình cân nhắc dòng iPhone 15, nhưng giá hơi cao. Bạn có thể giảm giá không?"},{"speaker":"salebot","text":"Dạ, mình có chương trình khuyến mại ưu đãi cho khách hàng mới. Bạn có thể mua trả góp 0% lãi suất trong 12 tháng hoặc nhận quà tặng kèm như tai nghe không dây."},{"speaker":"client","text":"Nghe hay đấy! Mình chọn trả góp 0% đi. Bạn gửi link đặt hàng cho mình nhé."},{"speaker":"salebot","text":"Dạ, cảm ơn bạn đã mua hàng! Đây là link đặt hàng: [link]. Sau khi thanh toán, mình sẽ gửi đơn hàng ngay cho bạn. Chúc bạn có trải nghiệm mua sắm tuyệt vời!"}]','successs',88),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm kiếm một chiếc bàn làm việc nhỏ gọn cho phòng ngủ. Có gì giới thiệu không?"},{"speaker":"salebot","text":"Chào chị! Mình rất vui khi được tư vấn cho chị. Chúng mình có bàn làm việc gỗ thông 3 ngăn, kích thước 120x50cm, vừa gọn nhẹ vừa chắc chắn. Giá chỉ 1.299.000đ thôi!"},{"speaker":"client","text":"Ôi, giá hơi cao so với mong đợi của mình. Có giảm giá không?"},{"speaker":"salebot","text":"Chị nhỉ, hôm nay có chương trình khuyến mại 10% cho sản phẩm này nếu chị đặt ngay! Giảm còn 1.169.000đ thôi ạ."},{"speaker":"client","text":"Tuyệt quá! Mình chọn màu gỗ tự nhiên nhé. Địa chỉ giao là 123 Đường Lê Lợi, Quận 1, TPHCM."},{"speaker":"salebot","text":"Dạ vâng chị! Đơn hàng của chị đã được ghi nhận. Chúng mình sẽ giao trong vòng 2-3 ngày làm việc. Cảm ơn chị đã mua sắm cùng shop!"}]','successs',89),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc điện thoại thông minh tầm trung, giá khoảng 5-7 triệu thôi. Bạn có thể giới thiệu cho mình vài mẫu không?"},{"speaker":"salebot","text":"Chào bạn! Dạ vâng, mình rất vui được hỗ trợ. Hiện tại chúng mình đang có ưu đãi siêu hấp dẫn cho chiếc Xiaomi Redmi Note 12 4GB/128GB chỉ 5,99 triệu, giao hàng miễn phí trong 24h. Bạn muốn xem ảnh, thông số hay ưu đãi chi tiết không ạ?"},{"speaker":"client","text":"Ui, giá tốt thế! Mình thích màu xanh dương. Còn bảo hành bao lâu vậy? Có ưu đãi trả góp không?"},{"speaker":"salebot","text":"Dạ bảo hành chính hãng 12 tháng ạ! Trả góp 0% lãi suất nếu bạn dùng thẻ tín dụng ngân hàng đối tác. Bạn có muốn mình gửi link đặt hàng ngay không? Hoặc bạn muốn tư vấn thêm về sản phẩm ạ?"},{"speaker":"client","text":"Ok, mình quyết định mua luôn! Gửi link đi nhé, mình thanh toán online luôn. Cảm ơn bạn nhiều!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Chúc bạn mua sắm vui vẻ. Đơn hàng của bạn đã được xác nhận, chúng mình sẽ giao trong ngày mai ạ. Cảm ơn bạn đã tin tưởng sản phẩm của chúng mình!"}]','successs',90),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm mua một chiếc điện thoại mới. Có sản phẩm nào tốt và giá cả phải chăng không?"},{"speaker":"salebot","text":"Chào chị ạ! Hiện tại em có chiếc iPhone 13 128GB đang khuyến mại chỉ còn 12 triệu thôi chị nhé. Máy còn mới nguyên hộp, bảo hành 12 tháng luôn!"},{"speaker":"client","text":"Ồ, giá hơi cao so với dự định của tôi. Có đợt giảm giá nào sắp tới không?"},{"speaker":"salebot","text":"Dạ thưa chị, tuần sau sẽ có đợt sale 5% vào ngày 15/8 chị nhé! Em có thể giữ máy cho chị đến lúc đó, chị cứ yên tâm."},{"speaker":"client","text":"Thế à, vậy tôi đặt trước 1 chiếc iPhone 13 128GB đi. Nhưng phải giao trong tuần này mới được chứ?"},{"speaker":"salebot","text":"Dạ vâng chị! Em sẽ giao trong 2 ngày tới, đúng hẹn ạ. Chị để lại số điện thoại và địa chỉ để em xác nhận đơn hàng nhé!"}]','successs',91),
('[{"speaker":"client","text":"Chào bạn! Mình đang tìm mua một chiếc điện thoại mới, nhưng không biết nên chọn loại nào. Bạn có thể tư vấn giúp mình không?"},{"speaker":"salebot","text":"Chào bạn! Tất nhiên rồi! Bạn đang quan tâm dòng điện thoại nào, tầm giá bao nhiêu, hay có nhu cầu gì đặc biệt không?"},{"speaker":"client","text":"Mình muốn chiếc điện thoại có camera tốt, pin khỏe, tầm 10-15 triệu thôi. Đang phân vân giữa iPhone 13 cũ và một số dòng Android."},{"speaker":"salebot","text":"Nếu vậy mình đề xuất chiếc iPhone 13 128GB nhé! Camera 12MP siêu nét, pin 8h sử dụng liên tục, và giá chỉ 12 triệu thôi. Bên mình có bảo hành 12 tháng đấy!"},{"speaker":"client","text":"Nghe ổn đấy! Mình có thể thanh toán online không? Ship nhanh không?"},{"speaker":"salebot","text":"Dạ có ạ! Bạn thanh toán online qua MoMo/VNPay đều được, ship trong 2h nếu ở nội thành Hà Nội. Mình gửi link đặt hàng luôn nhé?"},{"speaker":"client","text":"Ok, mình đặt luôn! Cảm ơn bạn nhiều nhé!"},{"speaker":"salebot","text":"Cảm ơn bạn đã mua hàng! Chúc bạn trải nghiệm sản phẩm tuyệt vời! Hẹn gặp lại!"}]','successs',92),
('[{"speaker":"client","text":"Chào bạn! Tôi đang tìm mua một chiếc điện thoại mới, có thể tư vấn giúp tôi không?"},{"speaker":"salebot","text":"Chào chị! Tất nhiên rồi ạ. Chị đang quan tâm đến dòng điện thoại nào? Budget khoảng bao nhiêu?"},{"speaker":"client","text":"Tôi thích dòng iPhone, nhưng giá hơi cao. Có mẫu nào tầm 15-20 triệu không?"},{"speaker":"salebot","text":"Dạ, chị có thể tham khảo iPhone 12 64GB ạ. Mẫu này vừa ra mắt, giá chỉ 18 triệu thôi ạ. Còn kèm quà tặng là tai nghe không dây nữa!"},{"speaker":"client","text":"Nghe hay đấy! Tôi có thể mua online không? Giao hàng nhanh không?"},{"speaker":"salebot","text":"Dạ có ạ! Chị chỉ cần chọn sản phẩm, thanh toán online, chúng tôi giao tận nhà trong 2 giờ ạ. Chị có muốn tôi giữ hàng không?"},{"speaker":"client","text":"Ok, tôi chọn iPhone 12 64GB nhé. Thanh toán qua MoMo được không?"},{"speaker":"salebot","text":"Dạ được ạ! Chị vui lòng cung cấp địa chỉ giao hàng để chúng tôi xử lý đơn hàng nhé. Cảm ơn chị đã mua sắm cùng chúng tôi!"}]','successs',93),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm mua một chiếc bàn học cho con gái tôi. Nó học lớp 5 nên cần bàn vừa vặn. Bạn có gì gợi ý không?"},{"speaker":"salebot","text":"Chào chị! Chúng tôi có bàn học trẻ em với kích thước 120x60cm phù hợp cho lứa tuổi của cháu. Mẫu này có 3 màu xanh, hồng, vàng và giá 1.200.000đ. Chị muốn xem ảnh không?"},{"speaker":"client","text":"À, tôi thấy giá hơi cao so với ngân sách. Có bàn nào rẻ hơn không? Cháu tôi cũng không cần quá cầu kỳ đâu."},{"speaker":"salebot","text":"Chị thông cảm ạ, sản phẩm này dùng gỗ công nghiệp bền và an toàn cho trẻ. Nếu chị cần tiết kiệm hơn, chúng tôi có bàn nhựa giá 500.000đ nhưng không có ngăn kéo. Chị thấy sao?"},{"speaker":"client","text":"Thế à... Vậy thôi, tôi sẽ suy nghĩ thêm. Cảm ơn bạn nhé!"}]','fail',94),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm mua một chiếc điện thoại thông minh tầm trung. Bạn có thể giới thiệu cho tôi vài mẫu không?"},{"speaker":"salebot","text":"Chào anh/chị ạ! Với ngân sách tầm trung, em đề xuất mẫu **Xiaomi Redmi Note 12 Pro 5G** – cấu hình mạnh mẽ (Snapdragon 778G, RAM 8GB), màn hình AMOLED 120Hz, pin 5000mAh. Giá chỉ 6.990.000đ thôi ạ!"},{"speaker":"client","text":"Mình nghe nói dòng này hay nóng máy lắm nhỉ? Có cách nào giảm nhiệt độ không?"},{"speaker":"salebot","text":"Dạ, em xin lỗi vì thông tin chưa đầy đủ ạ! Redmi Note 12 Pro có hệ thống tản nhiệt Graphite 3D, quạt hơi 3D và phần mềm tối ưu nhiệt độ. Anh có thể trải nghiệm mượt mà trong suốt quá trình sử dụng. Anh muốn đặt hàng luôn không ạ?"},{"speaker":"client","text":"Ok, mình thích rồi! Bạn gửi hàng tận nơi được chứ? Mình ở Hà Nội."},{"speaker":"salebot","text":"Dạ tất nhiên rồi ạ! Em sẽ gửi hàng **MIỄN PHÍ SHIP** trong 24 giờ tới. Anh có thể thanh toán bằng tiền mặt, chuyển khoản hoặc trả góp 0% ạ. Anh chọn phương thức nào?"},{"speaker":"client","text":"Mình chuyển khoản nhé. Gửi mã QR qua đây cho mình."},{"speaker":"salebot","text":"Dạ vâng ạ! Đây là mã QR thanh toán ạ [QR code]. Sau khi thanh toán xong, anh vui lòng gửi tin nhắn xác nhận cho em để em xử lý đơn hàng luôn ạ! Cảm ơn anh đã tin tưởng sản phẩm của shop!"}]','successs',95),
('[{"speaker":"client","text":"Tôi đang tìm mua một đôi giày thể thao cho con trai tôi, cháu 12 tuổi. Cháu rất thích chơi bóng đá."},{"speaker":"salebot","text":"Chào anh/chị! Tôi thấy anh/chị quan tâm đến sản phẩm giày thể thao cho bé trai 12 tuổi. Để tôi giới thiệu cho anh/chị đôi giày bóng đá chất lượng tốt nhé!"},{"speaker":"client","text":"Tôi chỉ có khoảng 800k thôi. Có đôi nào phù hợp không?"},{"speaker":"salebot","text":"Dạ, với ngân sách 800k thì tôi thấy đôi giày này khá phù hợp: giày thể thao đa năng, giá 790k, có đế chống trơn, màu xanh dương rất đẹp."},{"speaker":"client","text":"Màu sắc thì được, nhưng cháu tôi hay chạy nhảy nhiều lắm. Đôi giày này có bền không?"},{"speaker":"salebot","text":"Dạ, sản phẩm được làm từ chất liệu vải chống mài mòn cao, bảo hành 6 tháng. Tuy nhiên, với mức giá này thì độ bền cũng chỉ ở mức trung bình thôi ạ."},{"speaker":"client","text":"Vậy thôi, tôi không mua nữa. Cảm ơn nhé!"}]','fail',96),
('[{"speaker":"client","text":"Chào bạn! Tôi đang tìm mua một chiếc áo sơ mi nam chất lượng, giá tầm 500-700k thôi."},{"speaker":"salebot","text":"Chào anh! Rất cảm ơn anh đã quan tâm sản phẩm của chúng tôi. Hiện tại chúng tôi có bộ sưu tập áo sơ mi nam từ chất liệu cotton thoáng mát, giá từ 450k. Anh có thể xem trước sản phẩm tại đây: [link]."},{"speaker":"client","text":"À, tôi thấy mẫu này hơi đơn giản quá. Tôi thích kiểu có họa tiết nhẹ nhàng, kiểu cách hơn một chút."},{"speaker":"salebot","text":"Dạ vâng, tôi hiểu ạ. Hiện tại chúng tôi cũng có mẫu áo sơ mi nhung với họa tiết caro nhỏ, giá 680k. Anh có thể tham khảo xem có ưng không nhé?"},{"speaker":"client","text":"Nhung à? Tôi không thích chất liệu nhung lắm, cảm giác nóng. Tôi cần mặc đi làm hàng ngày cơ."},{"speaker":"salebot","text":"Dạ, tôi xin lỗi vì sự bất tiện này ạ. Chúng tôi có mẫu áo sơ mi linen pha cotton, thoáng mát, giá 620k. Nó vừa nhẹ nhàng, vừa thoải mái cho việc đi làm. Anh xem thử nhé?"},{"speaker":"client","text":"Linen à? Tôi nghe nói nó dễ nhăn lắm. Tôi không thích loại hay nhăn đâu."},{"speaker":"salebot","text":"Dạ, tôi xin lỗi vì sự bất tiện này ạ. Hiện tại chúng tôi có mẫu áo sơ mi từ chất liệu Tencel, vừa thoáng mát, ít nhăn, giá 720k. Anh có thể tham khảo thêm nhé?"},{"speaker":"client","text":"Tencel à? Đắt quá. Tôi thấy 720k hơi quá so với ngân sách của mình. Thôi tôi nghĩ sẽ tìm nơi khác vậy."}]','fail',97),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm mua một chiếc bàn làm việc cho phòng khách nhỏ. Có gì gợi ý không?"},{"speaker":"salebot","text":"Chào chị! Em có bàn làm việc gấp gọn màu trắng, kích thước 120x60cm, giá 1.200.000đ. Chị có quan tâm không?"},{"speaker":"client","text":"Ôi, hơi nhỏ so với nhu cầu của tôi. Tôi cần khoảng 150x70cm ấy. Có loại nào khác không?"},{"speaker":"salebot","text":"Dạ, em có bàn 150x70cm màu gỗ sồi, nhưng giá 2.800.000đ chị nhé. Chị có xem qua không?"},{"speaker":"client","text":"Trời ơi, đắt quá! Tôi chỉ cần dùng tạm thôi, không muốn đầu tư nhiều thế. Bạn có loại rẻ hơn không?"},{"speaker":"salebot","text":"Dạ, em xin lỗi chị vì không đáp ứng được nhu cầu. Chúc chị có một ngày vui vẻ!"}]','fail',98),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc áo khoác mùa đông cho bé nhà mình. Bé trai 5 tuổi, có thể tư vấn giúp mình không?"},{"speaker":"salebot","text":"Chào chị, rất vui được hỗ trợ! Mình giới thiệu cho chị mẫu áo khoác chống gió, chống thấm này nhé. Chất liệu cotton dày, có lớp lót ấm, phù hợp với bé trai 5 tuổi. Giá chỉ 399k thôi ạ!"},{"speaker":"client","text":"Ồ, nghe hay đấy! Màu sắc có những màu gì vậy?"},{"speaker":"salebot","text":"Chị có thể chọn màu xanh navy, đỏ tươi hoặc cam sáng ạ. Màu cam rất nổi bật, dễ nhìn thấy bé ngoài trời lắm!"},{"speaker":"client","text":"Mình thích màu xanh navy. Size thì mình chọn size 6 tuổi cho bé nhé, bé nhà mình hơi cao hơn tuổi."},{"speaker":"salebot","text":"Dạ vâng, size 6 tuổi vừa vặn ạ. Chị có thể đặt mua luôn không? Mình cam kết giao hàng trong 2 ngày tới ạ!"},{"speaker":"client","text":"Được rồi, mình đặt luôn nhé. Bao gồm phí ship không vậy?"},{"speaker":"salebot","text":"Dạ có chị nhé! Phí ship nội thành chỉ 20k, nhưng hôm nay shop đang miễn phí ship cho đơn trên 500k ạ. Đơn của chị là 399k nên chị được miễn phí ship luôn!"},{"speaker":"client","text":"Tuyệt vời! Mình gửi địa chỉ ở cuối bài viết nhé. Cảm ơn bạn nhiều!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Chị kiểm tra kỹ sản phẩm khi nhận hàng nhé. Chúc chị một ngày vui vẻ!"}]','successs',99),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc điện thoại mới. Bạn có thể tư vấn giúp mình không?"},{"speaker":"salebot","text":"Chào bạn! Tất nhiên rồi. Bạn đang tìm kiếm mẫu điện thoại nào? Mình có thể tư vấn theo nhu cầu sử dụng, ngân sách hoặc thương hiệu ưa thích của bạn."},{"speaker":"client","text":"Mình muốn một chiếc tầm trung, giá dưới 10 triệu, pin trâu, chụp ảnh đẹp. Bạn giới thiệu cho mình vài mẫu nhé!"},{"speaker":"salebot","text":"Dạ, mình giới thiệu bạn mẫu Xiaomi Redmi Note 12. Giá chỉ 8,9 triệu, pin 5000mAh, camera 50MP. Mẫu này rất được ưa chuộng trong tầm giá đấy!"},{"speaker":"client","text":"Nghe hay đấy. Mình muốn xem màu sắc và xem hàng trực tiếp luôn. Bạn có shop nào gần mình không?"},{"speaker":"salebot","text":"Shop mình có cửa hàng tại 123 Lê Lợi, Quận 1, TP.HCM. Bạn có thể đến xem mẫu trực tiếp từ 9h-21h hằng ngày. Mình gửi link Google Maps cho bạn nhé!"},{"speaker":"client","text":"Cảm ơn nhé. Mình sẽ đến ngay. Bạn giữ hàng cho mình nhé!"},{"speaker":"salebot","text":"Dạ, mình sẽ giữ hàng cho bạn đến 18h nay. Bạn cứ đến nhé! Cảm ơn bạn đã tin tưởng mua sắm cùng shop."}]','successs',100),
('[{"speaker":"client","text":"Chào bạn! Mình đang tìm một chiếc bàn học gỗ thông thoáng cho phòng ngủ nhỏ. Bạn có thể giới thiệu sản phẩm nào phù hợp không?"},{"speaker":"salebot","text":"Chào bạn! Mình rất vui khi được hỗ trợ. Bạn có thể tham khảo bàn học gỗ thông thoáng của thương hiệu EcoWood nhé! Giá chỉ 1.299.000đ, có 3 màu sắc và kích thước 120x60cm phù hợp phòng nhỏ."},{"speaker":"client","text":"Ồ, giá hơi cao nhỉ. Có ưu đãi gì không? Mình là sinh viên nên ngân sách hạn hẹp."},{"speaker":"salebot","text":"Đúng rồi! Hiện tại mình có voucher giảm 10% cho đơn hàng đầu tiên, cộng thêm phí ship miễn phí trong nội thành. Nếu bạn mua ngay hôm nay, mình sẽ tặng kèm 1 chiếc đèn bàn trị giá 150.000đ nữa!"},{"speaker":"client","text":"Wow, thế thì hợp lý quá! Mình chọn màu óc chó nhé. Bao giờ giao được?"},{"speaker":"salebot","text":"Cảm ơn bạn đã quyết định! Sản phẩm sẽ được giao trong vòng 2-3 ngày làm việc. Bạn vui lòng cung cấp địa chỉ và số điện thoại để mình xác nhận đơn hàng nhé!"}]','successs',101),
('[{"speaker":"client","text":"Chào bạn! Tôi đang tìm mua một chiếc điện thoại thông minh mới, nhưng không biết nên chọn loại nào. Bạn có thể tư vấn giúp tôi không?"},{"speaker":"salebot","text":"Chào bạn! Tôi rất vui khi được tư vấn cho bạn. Bạn có nhu cầu gì đặc biệt ở chiếc điện thoại không? Ví dụ như dung lượng pin, camera, hay hiệu năng?"},{"speaker":"client","text":"Tôi muốn một chiếc điện thoại có camera tốt, dung lượng pin lớn, và giá dưới 10 triệu thôi."},{"speaker":"salebot","text":"Vậy tôi giới thiệu cho bạn chiếc [Tên sản phẩm] với camera 48MP, pin 5000mAh và giá chỉ 9.5 triệu. Bạn có muốn xem chi tiết hơn không?"},{"speaker":"client","text":"Ừ, tôi xem qua thông số rồi. Nhưng mà tôi thấy nó hơi nặng so với tưởng tượng của mình. Có sản phẩm nào nhẹ hơn không?"},{"speaker":"salebot","text":"Dạ, sản phẩm nhẹ hơn một chút là [Tên sản phẩm khác] với camera 32MP, pin 4000mAh và giá 11 triệu. Bạn có muốn xem không?"},{"speaker":"client","text":"11 triệu thì hơi quá ngân sách của tôi. Thôi tôi nghĩ lại vậy. Cảm ơn bạn nhé!"}]','fail',102),
('[{"speaker":"client","text":"Chào bạn! Tôi đang tìm kiếm một chiếc bàn học thông minh cho con gái tôi, nó vừa vào lớp 5. Bạn có thể giới thiệu sản phẩm phù hợp không?"},{"speaker":"salebot","text":"Chào chị! Cảm ơn chị đã quan tâm. Tôi gợi ý cho chị mẫu bàn học thông minh có đèn LED điều chỉnh được, chống cận và ngăn kéo rộng rãi. Chất liệu gỗ công nghiệp bền đẹp, phù hợp với không gian phòng học của bé."},{"speaker":"client","text":"Nghe hay đấy! Giá thành thế nào vậy? Tôi muốn mua ngay nếu hợp lý."},{"speaker":"salebot","text":"Hiện tại sản phẩm đang khuyến mại chỉ còn 2.990.000đ (giá gốc 3.500.000đ). Đi kèm còn tặng bé 1 bộ dụng cụ học tập trị giá 200.000đ nữa chị nhé!"},{"speaker":"client","text":"Ồ, giá tốt quá! Tôi chọn màu gỗ tự nhiên nhé. Bao giờ giao được hàng?"},{"speaker":"salebot","text":"Cảm ơn chị đã đặt hàng! Hàng sẽ được giao trong 2-3 ngày làm việc tới địa chỉ chị cung cấp. Chị vui lòng kiểm tra kỹ sản phẩm khi nhận hàng nhé!"}]','successs',103),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm kiếm một chiếc bàn học gỗ chắc chắn cho phòng con trai mình. Nó phải đủ rộng để đặt máy tính và sách vở nữa."},{"speaker":"salebot","text":"Chào anh/chị ạ! Tôi rất vui khi được hỗ trợ. Hiện chúng tôi có bàn học bằng gỗ sồi cao cấp, mặt bàn rộng 120cm, kèm ngăn kéo đựng sách. Anh/chị có muốn xem ảnh sản phẩm không ạ?"},{"speaker":"client","text":"Vâng, gửi tôi ảnh sản phẩm luôn nhé. Giá cả thế nào? Tôi cần giao hàng tận nơi ở Hà Nội."},{"speaker":"salebot","text":"Dạ, sản phẩm có giá 3.500.000đ, giao hàng miễn phí trong nội thành Hà Nội. Anh/chị có thể thanh toán bằng tiền mặt hoặc chuyển khoản đều được ạ."},{"speaker":"client","text":"Tốt, tôi chọn mua chiếc bàn này luôn. Địa chỉ giao hàng là 123 Phố Huế, Hai Bà Trưng, Hà Nội."},{"speaker":"salebot","text":"Cảm ơn anh/chị đã mua hàng! Đơn hàng sẽ được giao trong vòng 3-5 ngày làm việc. Anh/chị vui lòng kiểm tra sản phẩm khi nhận hàng nhé. Còn gì thắc mắc nữa không ạ?"}]','successs',104),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm kiếm một chiếc bàn phím cơ cho công việc văn phòng. Bạn có thể giới thiệu sản phẩm tốt nhất không?"},{"speaker":"salebot","text":"Chào bạn! Tôi rất vui được hỗ trợ. Bạn muốn bàn phím cơ có đặc điểm gì nổi bật ạ? Ví dụ như độ êm, độ nảy, hay kiểu switch?"},{"speaker":"client","text":"Tôi cần bàn phím êm, phù hợp gõ lâu không mỏi tay. Budget khoảng 1-2 triệu."},{"speaker":"salebot","text":"Tôi đề xuất bạn sản phẩm [Bàn phím cơ Keychron K3](link) với switch Gateron Red siêu êm, giá chỉ 1.599.000đ. Có thể giao hàng ngay hôm nay ạ!"},{"speaker":"client","text":"Nghe ổn đấy! Tôi sẽ đặt hàng luôn. Bạn hỗ trợ thanh toán COD không?"},{"speaker":"salebot","text":"Dạ có ạ! Bạn vui lòng cung cấp địa chỉ giao hàng và số điện thoại để chúng tôi xử lý đơn hàng nhé. Cảm ơn bạn đã mua sắm cùng chúng tôi!"}]','successs',105),
('[{"speaker":"client","text":"Bên mình có bán đồ thể thao không? Mình đang cần mua một đôi giày chạy bộ."},{"speaker":"salebot","text":"Dạ, bên mình có bán nhiều mẫu giày chạy bộ nhập khẩu từ Nhật Bản ạ! Anh/chị muốn tìm mẫu nào ưu tiên thoải mái hay thiết kế thời trang?"},{"speaker":"client","text":"Mình thích thoải mái thôi. Nhưng giá hơi cao thế nhỉ, có giảm giá không?"},{"speaker":"salebot","text":"Dạ, hiện bên mình đang có chương trình khuyến mại 10% cho đơn hàng trên 2 triệu đồng. Anh/chị có thể tham khảo mẫu này giá 1.8 triệu, vừa túi tiền lắm!"},{"speaker":"client","text":"Ừm... nhưng mình thấy bên kia bán rẻ hơn nhiều. Thôi mình đi tìm chỗ khác vậy."}]','fail',106),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc điện thoại mới. Bạn có thể giới thiệu cho mình vài sản phẩm không?"},{"speaker":"salebot","text":"Chào bạn! Tất nhiên rồi. Bạn đang tìm kiếm dòng điện thoại nào, tầm giá bao nhiêu? Mình có thể gợi ý cho bạn một số mẫu hot hiện nay như Samsung Galaxy S23, iPhone 14 hay Xiaomi 13."},{"speaker":"client","text":"Mình thích dòng điện thoại tầm trung thôi, tầm 10-15 triệu. Mình không thích những sản phẩm quá đắt tiền."},{"speaker":"salebot","text":"Vậy mình xin giới thiệu đến bạn chiếc Xiaomi Redmi Note 12 4G với giá khoảng 4 triệu, cấu hình ổn định cho nhu cầu cơ bản. Hoặc nếu bạn muốn nâng cấp chút, chiếc Realme 10 Pro+ 5G tầm 12 triệu có camera tốt và màn hình AMOLED."},{"speaker":"client","text":"Mình thấy Realme 10 Pro+ 5G khá ưng, nhưng mình không thích thương hiệu Realme lắm. Có sản phẩm tương tự của hãng khác không?"},{"speaker":"salebot","text":"À, nếu bạn không thích Realme thì mình xin lỗi vì không thể giúp được. Hiện tại mình chỉ có sản phẩm của Xiaomi, Samsung và iPhone thôi. Bạn có thể xem xét lại nhé!"},{"speaker":"client","text":"Thế à... vậy thôi. Cảm ơn bạn nhé!"}]','fail',107),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm một chiếc áo khoác mùa đông cho bé trai 8 tuổi. Có loại nào bền và ấm không?"},{"speaker":"salebot","text":"Chào chị! Chúng tôi có sản phẩm áo khoác chống gió chống thấm, chất liệu cotton dày, phù hợp bé 8 tuổi. Giá 399k, bảo hành 1 năm. Chị muốn xem mẫu nào không?"},{"speaker":"client","text":"Tôi thích mẫu màu xanh dương. Có size M không?"},{"speaker":"salebot","text":"Có chị ơi! Size M vẫn còn 2 cái. Chị muốn đặt luôn không? Ship tận nhà trong 2 ngày."},{"speaker":"client","text":"Ok, tôi lấy 1 cái. Bao bì có giữ được kín không? Bé tôi hay làm rách áo lắm."},{"speaker":"salebot","text":"Dạ có chị! Bao bì đóng gói chắc chắn, chị yên tâm nhé. Chị vui lòng cung cấp địa chỉ và số điện thoại để chúng tôi xác nhận đơn hàng ạ!"}]','successs',108),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm mua một chiếc bàn phím cơ cho công việc văn phòng. Bạn có thể giới thiệu cho tôi một mẫu tốt không?"},{"speaker":"salebot","text":"Chào anh/chị ạ! Tôi rất vui khi được hỗ trợ. Hiện tại chúng tôi có bàn phím cơ Keychron K3 với switch Gateron Brown, êm ái và bền bỉ, phù hợp cho văn phòng. Anh/chị có nhu cầu màu sắc hay tính năng nào đặc biệt không?"},{"speaker":"client","text":"À, tôi thích kiểu cổ điển, không cầu kỳ. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ, giá niêm yết là 1.590.000đ, nhưng hôm nay ưu đãi giảm còn 1.450.000đ kèm quà tặng là dây cáp USB-C. Anh/chị có muốn đặt không ạ?"},{"speaker":"client","text":"Ok, tôi chọn màu đen. Ship nhanh trong ngày được không?"},{"speaker":"salebot","text":"Dạ được ạ! Chúng tôi cam kết giao trong ngày tại nội thành Hà Nội. Anh/chị vui lòng cung cấp địa chỉ và số điện thoại để tiện liên lạc. Cảm ơn anh/chị đã mua hàng!"}]','successs',109),
('[{"speaker":"client","text":"Chào bạn! Tôi đang tìm kiếm một đôi giày thể thao cho bé nhà tôi. Bé trai 8 tuổi, hay chạy nhảy lắm."},{"speaker":"salebot","text":"Chào chị! Rất vui khi được tư vấn cho chị. Bé trai 8 tuổi thì mình có dòng giày thể thao nhẹ nhàng, chống trơn tốt cho bé. Chị muốn màu gì ạ?"},{"speaker":"client","text":"Màu xanh dương hoặc xanh lá nhé. Chất liệu thoáng mát, dễ vệ sinh nữa."},{"speaker":"salebot","text":"Dạ, chúng tôi có dòng giày thể thao cho bé với chất liệu lưới thoáng khí, dễ vệ sinh ạ. Giá khoảng 500k - 700k. Chị muốn đặt không ạ?"},{"speaker":"client","text":"Hơi đắt quá. Tôi thấy bên khác có giá 350k thôi. Thôi tôi nghĩ lại vậy."},{"speaker":"salebot","text":"Dạ, em hiểu ạ. Nhưng sản phẩm của chúng em có chứng nhận an toàn cho bé, chống trơn tốt hơn ạ. Chị có thể cân nhắc thêm ạ?"},{"speaker":"client","text":"Thôi, tôi sẽ xem lại. Cảm ơn bạn nhé!"}]','fail',110),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm kiếm một chiếc bàn học gỗ thông minh cho bé nhà mình. Có sản phẩm nào phù hợp không?"},{"speaker":"salebot","text":"Chào chị! Chúng tôi có bàn học gỗ thông minh với thiết kế chống cong vẹo lưng, chống cận thị cho bé. Mẫu mới nhất vừa về hôm nay, chị có muốn xem ảnh sản phẩm không?"},{"speaker":"client","text":"Ồ, nghe hay đấy! Mình quan tâm đến mẫu màu nâu gỗ tự nhiên. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Mẫu chị thích đang khuyến mại 30% nhân dịp khai trương cửa hàng online, giá chỉ còn 1.990.000đ thay vì 2.840.000đ. Đi kèm còn tặng bộ dụng cụ học tập trị giá 200.000đ nữa ạ!"},{"speaker":"client","text":"Wow, ưu đãi hấp dẫn quá! Mình đặt luôn nhé. Giao hàng trong tuần này được không?"},{"speaker":"salebot","text":"Dạ được ạ! Chị vui lòng cung cấp địa chỉ nhận hàng để chúng tôi xác nhận đơn hàng. Ship tận nơi trong 3-5 ngày làm việc, miễn phí vận chuyển trên toàn quốc."}]','successs',111),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm mua một chiếc áo thể thao cho bé trai 8 tuổi. Có sản phẩm nào phù hợp không?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Chúng tôi có bộ sưu tập áo thể thao cho bé trai 8 tuổi với nhiều màu sắc và kích cỡ. Anh/chị muốn xem sản phẩm nào trước ạ?"},{"speaker":"client","text":"Tôi muốn xem mẫu áo có in hình siêu nhân ấy. Giá bao nhiêu thế?"},{"speaker":"salebot","text":"Dạ, mẫu áo siêu nhân có giá 199.000đ ạ. Nhưng hiện tại sản phẩm này đang hết hàng rồi ạ. Anh/chị có thể xem mẫu khác không ạ?"},{"speaker":"client","text":"Thế à? Chán thật. Tôi sẽ xem ở chỗ khác vậy. Cảm ơn nhé!"}]','fail',112),
('[{"speaker":"client","text":"Mình đang tìm kiếm một chiếc điện thoại có camera tốt, giá tầm 8-10 triệu. Bạn có sản phẩm nào phù hợp không?"},{"speaker":"salebot","text":"Chào bạn! Hiện tại chúng tôi có chiếc Xiaomi Redmi Note 12 giá 9.990.000đ với camera chính 50MP, rất phù hợp nhu cầu của bạn. Bạn muốn mình gửi link sản phẩm không?"},{"speaker":"client","text":"Ừ, gửi mình nhé. Mà mình thấy hình ảnh trông hơi to, có giảm giá không?"},{"speaker":"salebot","text":"Dạ có bạn nhé! Nếu mua ngay hôm nay thì mình có mã giảm giá 5% cho đơn hàng đầu tiên. Bạn có muốn mình hỗ trợ đặt hàng luôn không?"},{"speaker":"client","text":"Ok, mình đặt luôn. Bạn tư vấn giúp mình cách thanh toán và giao hàng nhé!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Bạn có thể thanh toán bằng chuyển khoản ngân hàng hoặc ví điện tử. Mình sẽ gửi hàng trong 24h và giao tận nơi. Cảm ơn bạn đã mua sắm cùng chúng tôi!"}]','successs',113),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc áo sơ mi nam chất lượng tốt, giá cả phải chăng thôi."},{"speaker":"salebot","text":"Chào anh! Cảm ơn anh đã quan tâm đến sản phẩm của chúng tôi. Hiện tại chúng tôi có nhiều mẫu áo sơ mi nam từ chất liệu cotton thoáng mát, giá từ 300.000đ đến 500.000đ. Anh có thích màu nào không?"},{"speaker":"client","text":"Mình thích màu xanh dương nhưng nhìn thấy trên mạng toàn toàn báo là áo bị co rút sau vài lần giặt."},{"speaker":"salebot","text":"Dạ, anh yên tâm nhé! Tất cả sản phẩm của chúng tôi đều được kiểm định chất lượng, không bị co rút sau giặt. Anh có thể xem thử video demo trên trang web của chúng tôi."},{"speaker":"client","text":"Thế còn size thì sao? Mình cao 1m85 nhưng hơi gầy, không biết có vừa không?"},{"speaker":"salebot","text":"Dạ, size L của chúng tôi phù hợp với chiều cao 1m75-1m85. Với vóc dáng gầy, anh có thể chọn size L hoặc size M đều được. Anh có thể tham khảo bảng size trên web."},{"speaker":"client","text":"À, mình cũng thấy shop hay giảm giá nhưng lúc mua xong lại tính thêm phí ship khá cao."},{"speaker":"salebot","text":"Dạ, anh ơi! Chúng tôi miễn phí ship cho đơn hàng trên 500.000đ. Nếu anh mua áo 400.000đ, anh có thể thêm 1 sản phẩm khác để đạt mức free ship nhé!"},{"speaker":"client","text":"Thôi được, mình nghĩ lại vậy. Cảm ơn nhé!"}]','fail',114),
('[{"speaker":"client","text":"Anh ơi, em đang tìm mua một chiếc tai nghe không dây để nghe nhạc thôi. Có loại nào tốt nhưng giá cả phải chăng không?"},{"speaker":"salebot","text":"Dạ chào chị, chúng em có dòng tai nghe không dây JBL Tune 510BT giá 1.290.000đ, chất lượng âm thanh tốt, chống ồn tạm ổn. Chị thấy sao?"},{"speaker":"client","text":"Em thấy hơi đắt so với túi tiền của em. Có loại nào rẻ hơn không?"},{"speaker":"salebot","text":"Dạ thôi ạ, vậy chị thử dòng Anker Soundcore Life Q20 giá 890.000đ, chống ồn có phần hơn, nhưng âm thanh cũng ổn. Chị thấy sao ạ?"},{"speaker":"client","text":"Em thấy cái này vẫn hơi nặng. Em muốn loại nhẹ nhàng, thiết kế nhỏ gọn thôi."},{"speaker":"salebot","text":"Dạ thôi ạ, vậy chị thử dòng Xiaomi Earbuds 3 Pro ạ, giá 790.000đ, nhẹ chỉ 4g, thiết kế nhỏ xinh. Chị thấy sao?"},{"speaker":"client","text":"Em thấy nó hơi to so với tai em. Thôi em đợi dịp khác vậy. Cảm ơn anh nhé!"}]','fail',115),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm mua một chiếc điện thoại thông minh để thay thế chiếc cũ của mình. Bạn có thể giới thiệu sản phẩm nào phù hợp không?"},{"speaker":"salebot","text":"Chào bạn! Tôi rất vui khi được hỗ trợ. Bạn muốn mua điện thoại cho mục đích gì ạ? Chụp ảnh, giải trí hay chỉ dùng các tính năng cơ bản?"},{"speaker":"client","text":"Tôi chủ yếu dùng mạng xã hội, gọi điện, nhắn tin và chụp ảnh đôi khi. Ngân sách của tôi khoảng 5-7 triệu đồng."},{"speaker":"salebot","text":"Tôi hiểu rồi ạ! Với ngân sách đó, tôi đề xuất chiếc **Xiaomi Redmi Note 12** nhé. Máy có camera 50MP, pin 5000mAh, màn hình AMOLED 90Hz, giá chỉ 6.990.000đ thôi!"},{"speaker":"client","text":"Nghe ổn đấy! Bạn có thể gửi link mua không? Và giao hàng trong bao lâu?"},{"speaker":"salebot","text":"Dạ vâng ạ! Link mua: [link sản phẩm]. Giao hàng miễn phí trong 2-3 ngày tới ạ. Bạn có muốn tôi giữ hàng sẵn không? Còn 3 chiếc cuối cùng trong kho!"},{"speaker":"client","text":"Vâng, giữ giùm tôi nhé! Tôi sẽ thanh toán online luôn. Cảm ơn bạn nhiều!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Chúc bạn mua sắm vui vẻ. Nếu có vấn đề gì, hãy liên hệ shop nhé! 😊"}]','successs',116),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc bàn làm việc mới. Có sản phẩm nào gợi ý không?"},{"speaker":"salebot","text":"Chào bạn! Mình rất vui khi hỗ trợ bạn. Bạn có nhu cầu về kích thước hay phong cách cụ thể không?"},{"speaker":"client","text":"Mình cần bàn rộng khoảng 120cm, màu gỗ tự nhiên, giá dưới 3 triệu thôi."},{"speaker":"salebot","text":"Rất tiếc ạ, sản phẩm phù hợp nhất của chúng tôi hiện có giá 3,5 triệu. Bạn có thể tham khảo mẫu khác giá 2,8 triệu nhưng kích thước hơi nhỏ, 110cm."},{"speaker":"client","text":"Ồ, vậy thôi. Mình không quan tâm lắm đến kích thước, nhưng 3,5 triệu hơi đắt so với dự định."},{"speaker":"salebot","text":"Em hiểu ạ. Nếu bạn muốn, mình sẽ gửi link giảm giá 5% nếu mua trong hôm nay nhé?"},{"speaker":"client","text":"Thế à? Hay quá! Nhưng mình cần suy nghĩ thêm chút. Cảm ơn bạn nhé."}]','fail',117),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc điện thoại mới. Mình nghe nói dòng iPhone 15 có nhiều cải tiến hay, bạn có thể giới thiệu qua không?"},{"speaker":"salebot","text":"Chào bạn! iPhone 15 vừa ra mắt với chip A16 Bionic mạnh mẽ, camera 48MP cải tiến và màn hình Super Retina XDR 6,1 inch. Bạn muốn màu sắc hay dung lượng lưu trữ nào?"},{"speaker":"client","text":"Mình thích màu xanh dương, dung lượng 256GB thôi. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dòng iPhone 15 256GB màu xanh dương hiện đang khuyến mại 23 triệu đồng, giảm 1 triệu so với giá niêm yết. Bạn có muốn mình hỗ trợ thanh toán trả góp 0% không?"},{"speaker":"client","text":"Tuyệt quá! Mình chọn trả góp 12 tháng đi. Bạn gửi link thanh toán luôn nhé."},{"speaker":"salebot","text":"Cảm ơn bạn đã mua hàng! Link thanh toán đã gửi qua email và tin nhắn. Chúc bạn trải nghiệm sản phẩm tuyệt vời!"}]','successs',118),
('[{"speaker":"client","text":"Chào bạn! Mình đang tìm kiếm một chiếc đàn guitar điện cho người mới chơi. Bạn có thể giới thiệu sản phẩm phù hợp không?"},{"speaker":"salebot","text":"Chào bạn! Rất vui khi được tư vấn. Mình đề xuất dòng đàn guitar điện **Yamaha Pacifica 012** - đây là sản phẩm phổ biến cho người mới bắt đầu, giá cả phải chăng chỉ khoảng 3 triệu đồng, chất lượng âm thanh tốt và dễ chơi."},{"speaker":"client","text":"Nghe ổn đấy! Mình thích màu đen. Bạn có thể check xem có sẵn hàng không?"},{"speaker":"salebot","text":"Dạ có ạ! Màu đen của model này vẫn còn hàng. Bạn muốn mình hỗ trợ đặt hàng luôn không?"},{"speaker":"client","text":"Ừ, mình quyết định mua luôn. Bao lâu thì giao được?"},{"speaker":"salebot","text":"Rất nhanh thôi ạ! Trong vòng 2-3 ngày làm việc sẽ giao tới tận nơi. Bạn có thể thanh toán qua chuyển khoản hoặc COD đều được."},{"speaker":"client","text":"Tuyệt! Mình chọn COD. Cảm ơn bạn nhiều nhé!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Chúc bạn chơi đàn vui vẻ. Nếu có gì thắc mắc sau này, hãy liên hệ mình nhé!"}]','successs',119),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm mua một chiếc máy hút bụi cầm tay cho gia đình. Bạn có thể giới thiệu cho tôi sản phẩm nào tốt nhất không?"},{"speaker":"salebot","text":"Dạ vâng ạ! Chúng tôi có sản phẩm máy hút bụi cầm tay Xiaomi Mi Handheld Vacuum 2 Lite, giá chỉ 1.990.000đ, rất tiết kiệm điện và dễ sử dụng. Bạn có nhu cầu mua không?"},{"speaker":"client","text":"Tôi thấy giá hơi cao, có sản phẩm nào rẻ hơn không? Tôi chỉ cần dùng trong nhà thôi."},{"speaker":"salebot","text":"Dạ thưa, chúng tôi cũng có sản phẩm Vinabox Mini, giá chỉ 990.000đ, nhưng công suất hơi yếu. Bạn có thể cân nhắc nhé!"},{"speaker":"client","text":"Thế thôi, tôi sẽ suy nghĩ thêm. Cảm ơn bạn nhé!"}]','fail',120),
('[{"speaker":"client","text":"Chào bạn! Tôi đang tìm kiếm một chiếc bàn học cho con gái tôi, nó 12 tuổi. Màu sắc nhẹ nhàng, chất liệu bền chắc ạ."},{"speaker":"salebot","text":"Chào chị! Chúng tôi có bàn học màu hồng pastel với chất liệu gỗ công nghiệp chống cong vênh, trọng lượng chịu tải 50kg. Chị có thể tham khảo sản phẩm này ạ!"},{"speaker":"client","text":"Giá bao nhiêu vậy? Tôi muốn biết thêm về chính sách giao hàng nữa."},{"speaker":"salebot","text":"Sản phẩm 1.200.000đ chị nhé! Giao hàng miễn phí trong 30km, thời gian 2-3 ngày. Đặc biệt, bảo hành 2 năm và đổi trả trong 7 ngày nếu có lỗi nhà sản xuất."},{"speaker":"client","text":"Tuyệt quá! Tôi chọn màu hồng. Làm thế nào để đặt hàng vậy?"},{"speaker":"salebot","text":"Chị vui lòng cung cấp địa chỉ giao hàng, số điện thoại, và chọn phương thức thanh toán (chuyển khoản hoặc COD). Tôi sẽ gửi link thanh toán qua Zalo/SMS ngay ạ!"}]','successs',121),
('[{"speaker":"client","text":"Anh ơi, em đang tìm kiếm một chiếc túi xách da thật đẹp cho dịp Tết này. Có loại nào vừa tiện dụng vừa sang trọng không vậy?"},{"speaker":"salebot","text":"Dạ em xin giới thiệu đến chị mẫu túi da lộn màu nâu này ạ! Chất liệu da thật 100%, thiết kế đơn giản nhưng rất tinh tế, phù hợp cho cả đi làm lẫn dịp lễ Tết. Chị có thể xem ảnh sản phẩm kèm thông tin chi tiết tại đây ạ!"},{"speaker":"client","text":"Ồ, mẫu này trông đẹp quá! Giá bao nhiêu vậy anh?"},{"speaker":"salebot","text":"Dạ sản phẩm hiện đang có giá 2.499.000đ, nhưng hôm nay là ngày đặc biệt nên em có thể giảm cho chị còn 2.299.000đ thôi ạ. Kèm theo đó là quà tặng là hộp đựng túi xinh xắn nữa!"},{"speaker":"client","text":"Wow, ưu đãi thế này thì em quyết định luôn rồi! Cho em đặt 1 chiếc màu nâu này nhé. Địa chỉ giao là..."},{"speaker":"salebot","text":"Dạ em ghi nhận đơn hàng của chị rồi ạ! Chị vui lòng kiểm tra tin nhắn để xác nhận thông tin giao hàng và thanh toán nha. Cảm ơn chị đã ủng hộ shop!"}]','successs',122),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc bàn làm việc mới. Có sản phẩm nào tốt và giá cả phải chăng không?"},{"speaker":"salebot","text":"Chào bạn! Mình rất vui khi được hỗ trợ. Bạn có thể tham khảo bàn làm việc gỗ thông 4 chân của chúng tôi. Giá chỉ 1.200.000đ, thiết kế chắc chắn, phù hợp cho không gian làm việc tại nhà."},{"speaker":"client","text":"Ồ, giá hơi cao so với mong đợi. Có sản phẩm nào rẻ hơn chút không?"},{"speaker":"salebot","text":"Dạ, chúng tôi cũng có bàn làm việc bằng nhựa composite giá 850.000đ, nhẹ nhàng, dễ vệ sinh. Hoặc bàn gấp gọn 700.000đ nếu bạn cần tiết kiệm tối đa."},{"speaker":"client","text":"Mình thích mẫu bàn gấp gọn ấy. Có màu sắc nào để lựa chọn không?"},{"speaker":"salebot","text":"Dạ có ạ! Màu đen, trắng và xám. Bạn thích màu nào nhất?"},{"speaker":"client","text":"Mình chọn màu xám nhé. Giao hàng trong bao lâu vậy?"},{"speaker":"salebot","text":"Dạ giao trong 3-5 ngày làm việc. Bạn có thể thanh toán khi nhận hàng hoặc chuyển khoản trước 30% để giữ đơn hàng."},{"speaker":"client","text":"Ok, mình chuyển khoản trước vậy. Cảm ơn bạn nhé!"},{"speaker":"salebot","text":"Cảm ơn bạn đã mua sắm! Chúng tôi sẽ gửi mã vận đơn qua tin nhắn ngay sau khi thanh toán thành công. Chúc bạn một ngày tốt lành!"}]','successs',123),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm một chiếc điện thoại chụp ảnh đẹp cho chị gái tôi. Cô ấy thích du lịch lắm."},{"speaker":"salebot","text":"Chào chị! Em thấy chị rất quan tâm đến chị gái mình. Điện thoại chụp ảnh đẹp nhất hiện nay là dòng iPhone 15 Pro Max với camera 48MP và ổn định hình ảnh cực tốt. Chị có muốn em giới thiệu thêm không?"},{"speaker":"client","text":"Ồ, nghe hay đấy! Cô ấy cũng thích quay video nữa. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ, em thấy chị quan tâm đến cả quay video nên gợi ý luôn ạ! iPhone 15 Pro Max có thể quay 4K 60fps, rất mượt. Giá niêm yết 32 triệu, nhưng hôm nay có chương trình khuyến mại chỉ 29 triệu thôi chị ạ!"},{"speaker":"client","text":"Wow, rẻ quá! Thế có bảo hành không? Giao hàng nhanh không?"},{"speaker":"salebot","text":"Dạ, bảo hành chính hãng 12 tháng ạ! Giao hàng miễn phí trong 24h nếu chị đặt ngay bây giờ. Chị có muốn em hỗ trợ đặt hàng luôn không?"},{"speaker":"client","text":"Được thôi, tôi chọn màu xanh dương nhé! Cảm ơn bạn nhiều."},{"speaker":"salebot","text":"Chị thật tốt bụng! Em đã ghi nhận đơn hàng ạ. Chúc chị gái chị có những bức ảnh du lịch thật đẹp. Cảm ơn chị đã tin tưởng sản phẩm của chúng em!"}]','successs',124),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm mua một chiếc áo sơ mi nam chất lượng tốt, giá tầm 500k-700k thôi."},{"speaker":"salebot","text":"Dạ vâng, chúng tôi có dòng áo sơ mi cotton 100% từ Nhật Bản, giá 650k, thoáng mát và bền lắm ạ!"},{"speaker":"client","text":"Ồ, nghe hay đó. Nhưng tôi thấy trên mạng có nhiều chỗ bán rẻ hơn, có giảm giá không?"},{"speaker":"salebot","text":"Dạ thưa anh, giá của chúng tôi đã niêm yết cạnh tranh rồi ạ. Nếu anh mua 2 cái thì giảm 5% nha!"},{"speaker":"client","text":"Thế à, nhưng tôi chỉ cần 1 cái thôi. Thôi để tôi suy nghĩ đã nhé."}]','fail',125),
('[{"speaker":"client","text":"Anh ơi, em đang tìm kiếm một chiếc điện thoại giá tầm 5 triệu thôi. Có mẫu nào tốt không?"},{"speaker":"salebot","text":"Dạ vâng, em có mẫu Oppo A16 giá 4.990.000đ, cấu hình ổn, pin trâu lắm ạ!"},{"speaker":"client","text":"Ui, 5 triệu thì được thôi. Nhưng em thấy nó hơi nặng, có mẫu nào nhẹ hơn không?"},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, trong phân khúc này hầu hết đều nặng cả. Em giới thiệu mẫu Vivo Y15S nhé, nó nhẹ hơn chút ạ!"},{"speaker":"client","text":"Vậy à... Nhưng em nghe nói Vivo hay bị lỗi phần mềm lắm. Có đảm bảo không?"},{"speaker":"salebot","text":"Dạ em xin lỗi, mình không thể cam kết được ạ. Em có thể tham khảo thêm trên các hội nhóm người dùng để quyết định ạ!"}]','fail',126),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm mua một chiếc điện thoại thông minh mới. Bạn có thể giới thiệu cho tôi vài mẫu không?"},{"speaker":"salebot","text":"Chào anh/chị ạ! Em xin giới thiệu dòng điện thoại Samsung Galaxy S24 vừa ra mắt ạ. Máy có màn hình 6.2 inch, chip Snapdragon 8 Gen 3, camera 50MP siêu nét. Giá hiện tại chỉ 22 triệu, kèm quà tặng là tai nghe không dây nhé!"},{"speaker":"client","text":"Wow, nghe hay đấy! Nhưng tôi thấy hơi mắc quá, có mẫu nào rẻ hơn không?"},{"speaker":"salebot","text":"Dạ em hiểu ạ, nếu anh/chị quan tâm dòng Samsung Galaxy A54 thì giá chỉ 11 triệu thôi ạ. Máy vẫn có màn hình Super AMOLED, camera 50MP, pin 5000mAh, phù hợp cho nhu cầu hàng ngày lắm ạ!"},{"speaker":"client","text":"Ừm, nghe cũng ổn. Bạn có thể ship tận nhà trong hôm nay không? Tôi đang ở quận 1."},{"speaker":"salebot","text":"Dạ có ạ! Em sẽ xử lý đơn hàng ngay bây giờ. Anh/chị vui lòng cung cấp địa chỉ cụ thể để em gửi đơn tới đơn vị vận chuyển nhé. Sau khi thanh toán online, anh/chị sẽ nhận hàng trong 2-4 tiếng ạ!"},{"speaker":"client","text":"Tuyệt vời! Tôi chọn mẫu Galaxy A54 nhé. Cảm ơn bạn nhiều!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Cảm ơn anh/chị đã tin tưởng sản phẩm của chúng em. Chúc anh/chị một ngày vui vẻ nhé! 😊"}]','successs',127),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc áo khoác mùa đông cho bé trai 5 tuổi. Bạn có thể giới thiệu sản phẩm không?"},{"speaker":"salebot","text":"Chào chị! Chúng tôi có áo khoác ấm cho bé trai 5 tuổi, giá từ 399k-799k. Loại vải cotton chống gió, có mũ trùm. Chị muốn xem ảnh không?"},{"speaker":"client","text":"Cảm ơn, nhưng mình thấy hơi đắt. Mình mới mua đồ cho bé thôi, nên ngại tốn nhiều tiền quá."},{"speaker":"salebot","text":"Dạ, chị có thể chọn gói combo áo + quần với giá 699k chị nhé. Rẻ hơn 20% so với mua lẻ."},{"speaker":"client","text":"Mình vẫn thấy hơi đắt. Thôi mình đi xem cửa hàng khác thôi, cảm ơn bạn nha!"}]','fail',128),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc điện thoại mới. Bạn có thể tư vấn cho mình không?"},{"speaker":"salebot","text":"Chào bạn! Mình rất vui khi được giúp bạn. Bạn đang quan tâm đến dòng điện thoại nào ạ? Có nhu cầu gì đặc biệt không?"},{"speaker":"client","text":"Mình muốn một chiếc có camera tốt, pin trâu, và giá tầm 10-12 triệu thôi. Bạn giới thiệu giúp mình nhé!"},{"speaker":"salebot","text":"Dạ, theo mình thì chiếc Xiaomi Redmi Note 12 Pro 5G 8GB/256GB đang bán 11,9 triệu, camera 200MP, pin 5000mAh rất phù hợp ạ. Bạn có muốn mình gửi link sản phẩm không?"},{"speaker":"client","text":"Ok, mình thấy cũng ổn. Bạn cho mình link và mình sẽ quyết định sau nhé!"},{"speaker":"salebot","text":"Dạ, đây là link sản phẩm: [link]. Mình sẽ gửi kèm mã giảm giá 5% nếu bạn mua trong hôm nay nhé! Bạn có cần hỗ trợ gì thêm không?"},{"speaker":"client","text":"Cảm ơn bạn nhé! Mình sẽ suy nghĩ và đặt hàng sau."},{"speaker":"salebot","text":"Dạ không có gì ạ! Chúc bạn mua sắm vui vẻ. Nếu cần gì thêm, cứ inbox mình nhé!"}]','successs',129),
('[{"speaker":"client","text":"Anh ơi, em đang tìm kiếm một chiếc túi xách da thật tiện dụng cho công việc. Có loại nào vừa gọn nhẹ vừa bền không?"},{"speaker":"salebot","text":"Dạ, chúng em có mẫu túi da chính hãng từ thương hiệu ABC, trọng lượng chỉ 500g, chống thấm nước và bảo hành 2 năm. Em thích màu gì ạ?"},{"speaker":"client","text":"Em thích màu nâu đen, nhưng có màu đen thuần không? Em ngại màu lòe loẹt quá."},{"speaker":"salebot","text":"Dạ, có ạ! Mẫu màu đen thuần này đang được giảm 15% trong tuần lễ vàng. Em muốn đặt ngay không ạ?"},{"speaker":"client","text":"Ok, thế anh cho em link thanh toán đi. Em chuyển tiền luôn nhé."},{"speaker":"salebot","text":"Dạ, link thanh toán đã gửi vào tin nhắn của em ạ. Sau khi chuyển khoản xong, em gửi ảnh biên lai cho shop để xác nhận đơn hàng nha!"}]','successs',130),
('[{"speaker":"client","text":"Chào bạn! Mình đang muốn mua một chiếc áo sơ mi nữ cho chị mình. Có loại nào đẹp và chất lượng không?"},{"speaker":"salebot","text":"Chào chị ạ! Chúng tôi có nhiều mẫu áo sơ mi nữ từ các thương hiệu uy tín như Uniqlo, Zara. Chị thích phong cách nào ạ? Cổ điển hay hiện đại?"},{"speaker":"client","text":"Hmm, chị mình thích sự đơn giản nhưng vẫn sang trọng. Có màu trắng không?"},{"speaker":"salebot","text":"Dạ có ạ! Áo sơ mi trắng cổ điển của chúng tôi có giá 399.000đ, chất liệu cotton thoáng mát. Chị có muốn xem ảnh mẫu không ạ?"},{"speaker":"client","text":"À, mình thấy giá hơi cao. Có đợt giảm giá nào không?"},{"speaker":"salebot","text":"Dạ hiện tại chúng tôi đang có chương trình tặng kèm khăn quàng 20.000đ khi mua áo, nhưng không giảm giá trực tiếp ạ. Chị có muốn tham khảo mẫu khác không?"},{"speaker":"client","text":"Thôi, mình nghĩ mình sẽ tìm chỗ khác. Cảm ơn bạn nhé!"}]','fail',131),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc đồng hồ thể thao để đi tập gym. Bạn có sản phẩm nào phù hợp không?"},{"speaker":"salebot","text":"Chào bạn! Tôi rất vui khi được hỗ trợ. Chúng tôi có chiếc **Đồng hồ thể thao XYZ Pro** với khả năng đo nhịp tim, đếm bước chân và chống nước chuẩn IP68, rất phù hợp cho việc tập luyện. Bạn thích màu sắc nào nhất?"},{"speaker":"client","text":"Mình thích màu đen. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Màu đen còn 1.299.000đ, đang có chương trình giảm giá 10% nếu mua trong hôm nay. Bạn có muốn đặt hàng luôn không?"},{"speaker":"client","text":"Ừ, mình lấy luôn. Bao giao hàng trong bao lâu vậy?"},{"speaker":"salebot","text":"Giao hàng miễn phí trong 2-3 ngày làm việc. Bạn có thể chọn phương thức thanh toán COD hoặc chuyển khoản. Mình sẽ gửi link thanh toán qua tin nhắn ngay nhé!"}]','successs',132),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua một chiếc áo khoác mùa đông. Bạn có thể tư vấn giúp mình không?"},{"speaker":"salebot","text":"Chào bạn! Mình rất vui được hỗ trợ. Bạn thích kiểu dáng nào? Áo khoác dài, ngắn hay bomber? Ngoài ra, bạn có thích màu sắc gì không?"},{"speaker":"client","text":"Mình thích kiểu áo khoác dài, màu xám hoặc đen. Ngoài ra, mình muốn chất liệu chống gió tốt."},{"speaker":"salebot","text":"Rất hợp lý! Chúng mình có áo khoác dài chống gió, chất liệu vải chống thấm nước, màu xám hoặc đen. Giá khoảng 1.200.000đ. Bạn có muốn xem ảnh sản phẩm không?"},{"speaker":"client","text":"Mình muốn xem ảnh sản phẩm trước đã. Có thể gửi link không?"},{"speaker":"salebot","text":"Chắc chắn rồi! Đây là link sản phẩm: [link]. Bạn có thấy ưng ý không?"},{"speaker":"client","text":"Áo nhìn khá ổn, nhưng mình muốn giảm giá một chút được không? Bạn có thể hỗ trợ không?"},{"speaker":"salebot","text":"Chúng mình đang có chương trình khuyến mãi giảm 10% cho khách hàng mới. Vậy giá cuối cùng sẽ là 1.080.000đ. Bạn đồng ý chứ?"},{"speaker":"client","text":"Ok, mình mua luôn. Bạn giúp mình đặt hàng đi."},{"speaker":"salebot","text":"Cảm ơn bạn đã mua hàng! Đơn hàng của bạn đã được ghi nhận. Chúng mình sẽ gửi xác nhận qua email và giao hàng trong 3-5 ngày. Chúc bạn một ngày tốt lành!"}]','successs',133),
('[{"speaker":"client","text":"Chào bạn! Mình đang tìm mua một chiếc áo khoác mùa đông cho bé trai 8 tuổi. Bạn có sản phẩm nào phù hợp không?"},{"speaker":"salebot","text":"Chào chị! Cảm ơn chị đã quan tâm. Chúng tôi có nhiều mẫu áo khoác cho bé trai 8 tuổi với chất liệu cotton ấm áp, màu sắc đa dạng. Chị muốn xem mẫu nào trước ạ?"},{"speaker":"client","text":"À mình thấy mẫu áo màu xanh dương trông khá dễ thương. Nhưng mình lo là bé hay nghịch nên sợ dễ bẩn lắm."},{"speaker":"salebot","text":"Chị yên tâm nhé! Mẫu này có lớp chống thấm nước và dễ vệ sinh lắm ạ. Chị có thể xem video hướng dẫn vệ sinh trên website nha."},{"speaker":"client","text":"Thế giá bao nhiêu vậy? Mình đang cân nhắc vì ngân sách hơi eo hẹp."},{"speaker":"salebot","text":"Dạ mẫu này có giá 590.000đ chị nhé. Nhưng chị có thể tham khảo mẫu khác rẻ hơn 390.000đ nếu quan trọng về giá ạ."},{"speaker":"client","text":"Ôi vậy thì hơi đắt quá. Mình sẽ suy nghĩ thêm rồi quay lại sau nhé. Cảm ơn bạn!"}]','fail',134),
('[{"speaker":"client","text":"Chào bạn! Tôi đang tìm mua một chiếc áo khoác mùa đông cho bé trai 5 tuổi. Có loại nào phù hợp không?"},{"speaker":"salebot","text":"Chào chị! Chúng tôi có nhiều mẫu áo khoác ấm áp cho bé trai 5 tuổi, từ 200.000đ đến 500.000đ. Chị muốn loại nào?"},{"speaker":"client","text":"Tôi muốn cái giá rẻ thôi, khoảng 250k. Loại nào bền và dễ giặt?"},{"speaker":"salebot","text":"Dạ chị ơi, mẫu rẻ nhất 250k này dùng chất liệu cotton pha, khá nhẹ nhưng dễ bị co sau vài lần giặt. Nếu chị chịu khó giặt tay thì ổn chị nhé."},{"speaker":"client","text":"Thế à... Chắc tôi không mua đâu. Cảm ơn bạn nhé!"}]','fail',135),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm mua một chiếc áo khoác mùa đông cho bé trai 10 tuổi. Giá tầm 500k-700k thôi nhé."},{"speaker":"salebot","text":"Dạ vâng ạ! Chúng tôi có dòng áo khoác chống gió chống nước cho bé, giá 650k. Màu xanh dương hoặc đen nhé?"},{"speaker":"client","text":"Màu xanh dương được. Nhưng mà bé tôi hơi mập, áo có size rộng không?"},{"speaker":"salebot","text":"Dạ có ạ! Size L rộng hơn size chuẩn 10cm, phù hợp với bé mập. Cháu mặc thử xem có vừa không ạ?"},{"speaker":"client","text":"Thế giao hàng mất bao lâu? Tôi cần gấp lắm."},{"speaker":"salebot","text":"Dạ giao trong 3-5 ngày làm việc ạ. Nếu cần gấp, mình có thể chọn giao nhanh trong 2 ngày nhưng phí ship 50k ạ."},{"speaker":"client","text":"Vậy giao nhanh đi. Nhưng mà tôi thấy trên mạng shop khác bán rẻ hơn 100k luôn."},{"speaker":"salebot","text":"Dạ shop mình cam kết chất lượng vải dày, chống rét tốt ạ. Đảm bảo bé mặc thoải mái lắm ạ. Mà shop đang có ưu đãi giảm 10% cho đơn đầu tiên ạ!"},{"speaker":"client","text":"Thôi được, tôi sẽ suy nghĩ đã. Cảm ơn nhé!"}]','fail',136),
('[{"speaker":"client","text":"Chào bạn! Tôi đang tìm kiếm một chiếc bàn học gỗ chắc chắn cho con gái tôi 10 tuổi. Bạn có thể tư vấn giúp tôi không?"},{"speaker":"salebot","text":"Chào chị! Tất nhiên rồi ạ. Chị muốn bàn gỗ tự nhiên hay gỗ công nghiệp? Màu sắc cũng như kích thước mong muốn của chị là gì ạ?"},{"speaker":"client","text":"Tôi thích gỗ tự nhiên vì bền và an toàn cho trẻ. Màu nâu nhạt hoặc trắng là được. Kích thước khoảng 120x60 cm thôi."},{"speaker":"salebot","text":"Dạ chị ạ, chúng tôi có bàn gỗ thông 120x60 cm màu nâu nhạt giá 2.890.000đ, mặt bàn chống trầy xước và có ngăn kéo nhỏ tiện lợi. Chị có muốn xem ảnh sản phẩm không ạ?"},{"speaker":"client","text":"Vâng, gửi tôi ảnh đi. Tôi cũng muốn biết về chế độ bảo hành nữa."},{"speaker":"salebot","text":"Dạ vâng ạ! Ảnh sản phẩm đã gửi vào Zalo của chị rồi ạ. Chiếc bàn được bảo hành 5 năm toàn quốc, giao hàng miễn phí trong 3 ngày. Chị có muốn đặt hàng luôn không ạ?"},{"speaker":"client","text":"Tôi thấy ổn rồi. Tôi chọn bàn gỗ thông màu nâu nhạt này. Làm thế nào để thanh toán vậy?"},{"speaker":"salebot","text":"Cảm ơn chị đã tin tưởng! Chị có thể thanh toán bằng chuyển khoản hoặc COD đều được ạ. Tôi sẽ gửi link thanh toán và đơn hàng ngay bây giờ ạ."}]','successs',137),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm mua một chiếc bàn học thông minh cho con gái tôi. Cháu sắp vào lớp 1 rồi, cần chỗ học thoải mái. Bạn có sản phẩm nào phù hợp không?"},{"speaker":"salebot","text":"Chào chị! Chúng tôi có bàn học thông minh chống cận cho trẻ em, vừa gọn nhẹ vừa có đèn LED điều chỉnh độ sáng. Chị muốn xem sản phẩm nào không ạ?"},{"speaker":"client","text":"À, vậy giá bao nhiêu vậy? Đỡ tốn tiền quá!"},{"speaker":"salebot","text":"Chị yên tâm ạ! Bàn chống cận loại 3 cấp độ chỉ 1.990.000đ, kèm bảo hành 2 năm. Đặc biệt hôm nay giảm còn 1.790.000đ nếu chị đặt ngay!"},{"speaker":"client","text":"Thế giao hàng có nhanh không? Tôi cần dùng gấp!"},{"speaker":"salebot","text":"Chị cứ yên tâm! Chúng tôi giao miễn phí trong 24h nội thành Hà Nội. Nếu chị ở tỉnh khác cũng chỉ 1-2 ngày thôi ạ."},{"speaker":"client","text":"Vậy tôi chọn luôn nhé! Mua luôn 1 bàn chống cận ấy. Địa chỉ giao là..."},{"speaker":"salebot","text":"Dạ chị vui lòng cung cấp tên, số điện thoại và địa chỉ giao hàng ạ. Cảm ơn chị đã tin tưởng sản phẩm của chúng tôi!"}]','successs',138),
('[{"speaker":"client","text":"Tôi đang tìm kiếm một chiếc áo khoác chống nước cho mùa đông này. Giá khoảng 1 triệu rưỡi thôi nhé."},{"speaker":"salebot","text":"Chào chị! Chúng tôi có mẫu áo khoác chống nước loại tốt với giá 1.8 triệu chị ạ. Chất liệu chống thấm tuyệt vời, phù hợp cho mùa đông lạnh này."},{"speaker":"client","text":"Hơi vượt quá ngân sách rồi. Có loại nào rẻ hơn không? Khoảng 1 triệu thôi ấy."},{"speaker":"salebot","text":"Dạ, mẫu rẻ nhất chúng tôi có là 1.2 triệu thôi chị. Nhưng chất liệu có phần kém hơn một chút, chị có thể xem thử nhé."},{"speaker":"client","text":"Thôi vậy, tôi sẽ suy nghĩ thêm. Cảm ơn nhé!"}]','fail',139),
('[{"speaker":"client","text":"Chào bạn, tôi đang tìm mua một chiếc áo khoác mùa đông cho con gái mình. Bạn có thể tư vấn giúp tôi không?"},{"speaker":"salebot","text":"Chào chị ạ! Tôi rất vui khi được hỗ trợ chị. Con gái chị tầm bao nhiêu tuổi rồi ạ? Và chị thích kiểu dáng hay màu sắc nào nhất?"},{"speaker":"client","text":"Con gái tôi 12 tuổi. Tôi thích kiểu dáng nhẹ nhàng, màu xanh dương hoặc hồng pastel."},{"speaker":"salebot","text":"Chị ơi, chúng tôi vừa nhập về dòng áo khoác trẻ em với chất liệu cotton chống gió, màu xanh dương nhạt và hồng pastel rất dễ thương ạ! Giá chỉ 399.000đ thôi."},{"speaker":"client","text":"Ôi, giá hơi cao so với dự định của tôi. Tôi chỉ định mua dưới 300k thôi."},{"speaker":"salebot","text":"Dạ, chị ơi! Tôi xin lỗi vì không thể đáp ứng được mong muốn của chị. Chúng tôi có dòng áo khoác giá 299.000đ nhưng màu sắc chỉ còn xanh lá và cam thôi ạ."},{"speaker":"client","text":"Thế à, tôi nghĩ tôi sẽ xem xét thêm. Cảm ơn bạn nhé!"}]','fail',140),
